sp_widget.client_script:
api.controller = function($timeout) {

  var c = this;


  /* =========================================================
     SIDEBAR
     ========================================================= */

  var sidebarKey =
    'campus360_trainer_sidebar_collapsed';


  c.sidebarCollapsed =
    localStorage.getItem(
      sidebarKey
    ) === 'true';


  c.toggleSidebar =
    function() {

      c.sidebarCollapsed =
        !c.sidebarCollapsed;


      localStorage.setItem(
        sidebarKey,
        c.sidebarCollapsed
          ? 'true'
          : 'false'
      );

    };


  /* =========================================================
     CURRENT TRAINER
     ========================================================= */

  c.currentTrainerId =
    (
      c.data.trainer &&
      c.data.trainer.id
    )
      ? c.data.trainer.id
      : '';


  /* =========================================================
     TABS
     ========================================================= */

  c.activeTab =
    'overview';


  c.setTab =
    function(tab) {

      c.activeTab =
        tab;


      c.assignmentError =
        '';


      c.attendanceMessage =
        '';

    };


  /* =========================================================
     DATE HELPERS
     ========================================================= */

  function dateObject(
    value
  ) {

    if (!value) {

      return new Date();

    }


    var text =
      String(value)
        .substring(
          0,
          10
        );


    var parts =
      text.split('-');


    if (
      parts.length != 3
    ) {

      return new Date();

    }


    return new Date(

      parseInt(
        parts[0],
        10
      ),

      parseInt(
        parts[1],
        10
      ) - 1,

      parseInt(
        parts[2],
        10
      )

    );

  }


  function formatDate(
    value
  ) {

    var d =
      dateObject(
        value
      );


    var month =
      String(
        d.getMonth() + 1
      );


    var day =
      String(
        d.getDate()
      );


    if (
      month.length == 1
    ) {

      month =
        '0' +
        month;

    }


    if (
      day.length == 1
    ) {

      day =
        '0' +
        day;

    }


    return (

      d.getFullYear() +
      '-' +
      month +
      '-' +
      day

    );

  }


  function isDateInProgram(
    value
  ) {

    if (
      !c.data.selectedProgram
    ) {

      return false;

    }


    var selected =
      formatDate(
        value
      );


    var start =
      c.data.selectedProgram.startDate;


    var end =
      c.data.selectedProgram.endDate;


    if (
      start &&
      selected < start
    ) {

      return false;

    }


    if (
      end &&
      selected > end
    ) {

      return false;

    }


    return true;

  }


  /* =========================================================
     ATTENDANCE INITIAL DATE
     ========================================================= */

  c.attendanceDate =

    c.data &&
    c.data.attendanceDate

      ? dateObject(
          c.data.attendanceDate
        )

      : (
          c.data &&
          c.data.selectedProgram &&
          c.data.selectedProgram.startDate

            ? dateObject(
                c.data.selectedProgram.startDate
              )

            : new Date()
        );


  c.savingAttendance =
    false;


  c.attendanceMessage =
    '';


  c.attendanceMessageType =
    '';


  c.attendanceDateError =
    '';


  /* =========================================================
     LOAD ATTENDANCE DATE
     ========================================================= */

  c.loadAttendanceForDate =
    function() {

      c.attendanceMessage =
        '';

      c.attendanceDateError =
        '';


      if (
        !c.data.selectedProgram
      ) {

        return;

      }


      var selected =
        formatDate(
          c.attendanceDate
        );


      if (
        !isDateInProgram(
          c.attendanceDate
        )
      ) {

        c.attendanceDateError =
          'Please select a date inside the training period.';

        return;

      }


      c.server.get({

        action:
          'load_attendance',

        trainer:
          c.currentTrainerId,

        training:
          c.data.selectedProgram.sys_id,

        date:
          selected

      }).then(
        function(response) {

          if (
            response &&
            response.data
          ) {

            if (
              response.data.attendanceRows
            ) {

              c.data.selectedProgram.attendanceRows =
                response.data.attendanceRows;

            }


            if (
              response.data.attendanceDateError
            ) {

              c.attendanceDateError =
                response.data.attendanceDateError;

            }

          }

        }
      );

    };


  /* =========================================================
     SAVE ATTENDANCE
     ========================================================= */

  c.saveAttendance =
    function() {

      if (
        !c.data.selectedProgram
      ) {

        return;

      }


      if (
        !isDateInProgram(
          c.attendanceDate
        )
      ) {

        c.attendanceDateError =
          'Please select a date inside the training period.';

        return;

      }


      var rows =
        c.data.selectedProgram
          .attendanceRows || [];


      var records =
        [];


      for (
        var i = 0;
        i < rows.length;
        i++
      ) {

        records.push({

          studentSysId:
            rows[i].studentSysId,

          status:
            rows[i].status || '',

          remarks:
            rows[i].remarks || ''

        });

      }


      c.savingAttendance =
        true;


      c.server.get({

        action:
          'save_attendance',

        trainer:
          c.currentTrainerId,

        training:
          c.data.selectedProgram.sys_id,

        date:
          formatDate(
            c.attendanceDate
          ),

        records:
          records

      }).then(
        function(response) {

          c.savingAttendance =
            false;


          c.attendanceMessage =
            response.data.saveMessage || '';


          c.attendanceMessageType =
            response.data.saveSuccess
              ? 'success'
              : 'error';


          if (
            response.data.saveSuccess
          ) {

            c.loadAttendanceForDate();

          }

        }
      );

    };


  /* =========================================================
     OPEN PROGRAM
     ========================================================= */

  c.openProgram =
    function(program) {

      if (
        !program ||
        !program.sys_id
      ) {

        return;

      }


      c.activeTab =
        'overview';


      c.data.selectedProgramId =
        program.sys_id;


      c.attendanceDate =
        dateObject(
          program.startDate
        );


      c.server.get({

        action:
          'load_program',

        trainer:
          c.currentTrainerId,

        training:
          program.sys_id,

        date:
          program.startDate

      }).then(
        function(response) {

          if (
            response &&
            response.data &&
            response.data.selectedProgram
          ) {

            c.data.selectedProgram =
              response.data.selectedProgram;


            c.data.selectedProgramId =
              response.data.selectedProgram.sys_id;

          }


          $timeout(
            function() {

              var element =
                document.getElementById(
                  'campus360-selected-training'
                );


              if (element) {

                element.scrollIntoView({
                  behavior: 'smooth',
                  block: 'start'
                });

              }

            },
            100
          );

        }
      );

    };


  /* =========================================================
     CREATE ASSIGNMENT
     ========================================================= */

  c.assignmentModalOpen =
    false;


  c.savingAssignment =
    false;


  c.assignmentError =
    '';


  c.assignmentForm =
    {};


  c.openCreateAssignment =
    function() {

      if (
        !c.data.selectedProgram
      ) {

        return;

      }


      c.assignmentForm = {

        name:
          '',

        type:
          'Coding',

        description:
          '',

        resourceLink:
          '',

        assignedDate:
          dateObject(
            c.data.selectedProgram.startDate
          ),

        dueDate:
          dateObject(
            c.data.selectedProgram.endDate
          ),

        maximumScore:
          100

      };


      c.assignmentError =
        '';


      c.assignmentModalOpen =
        true;

    };


  c.closeAssignmentModal =
    function() {

      c.assignmentModalOpen =
        false;

      c.assignmentError =
        '';

    };


  /* =========================================================
     SAVE / PUBLISH ASSIGNMENT
     ========================================================= */

  c.saveAssignment =
    function(mode) {

      c.assignmentError =
        '';


      if (
        !c.assignmentForm.name ||
        !String(
          c.assignmentForm.name
        ).trim()
      ) {

        c.assignmentError =
          'Assignment name is required.';

        return;

      }


      if (
        !c.assignmentForm.assignedDate
      ) {

        c.assignmentError =
          'Assigned date is required.';

        return;

      }


      if (
        !c.assignmentForm.dueDate
      ) {

        c.assignmentError =
          'Due date is required.';

        return;

      }


      if (
        formatDate(
          c.assignmentForm.dueDate
        )
        <
        formatDate(
          c.assignmentForm.assignedDate
        )
      ) {

        c.assignmentError =
          'Due date cannot be before assigned date.';

        return;

      }


      if (
        !c.assignmentForm.maximumScore ||
        Number(
          c.assignmentForm.maximumScore
        ) <= 0
      ) {

        c.assignmentError =
          'Maximum score must be greater than zero.';

        return;

      }


      c.savingAssignment =
        true;


      c.server.get({

        action:
          'create_assignment',

        trainer:
          c.currentTrainerId,

        training:
          c.data.selectedProgram.sys_id,

        name:
          String(
            c.assignmentForm.name
          ).trim(),

        assignmentType:
          c.assignmentForm.type,

        description:
          c.assignmentForm.description || '',

        resourceLink:
          c.assignmentForm.resourceLink || '',

        assignedDate:
          formatDate(
            c.assignmentForm.assignedDate
          ),

        dueDate:
          formatDate(
            c.assignmentForm.dueDate
          ),

        maximumScore:
          c.assignmentForm.maximumScore,

        mode:
          mode

      }).then(
        function(response) {

          c.savingAssignment =
            false;


          if (
            response &&
            response.data &&
            response.data.createSuccess
          ) {

            c.assignmentModalOpen =
              false;


            c.refreshSelectedProgram();

          } else {

            c.assignmentError =
              response.data.createMessage ||
              'Unable to create assignment.';

          }

        }
      );

    };


  /* =========================================================
     REFRESH SELECTED PROGRAM
     ========================================================= */

  c.refreshSelectedProgram =
    function() {

      if (
        !c.data.selectedProgram
      ) {

        return;

      }


      c.server.get({

        action:
          'load_program',

        trainer:
          c.currentTrainerId,

        training:
          c.data.selectedProgram.sys_id,

        date:
          formatDate(
            c.attendanceDate
          )

      }).then(
        function(response) {

          if (
            response &&
            response.data &&
            response.data.selectedProgram
          ) {

            c.data.selectedProgram =
              response.data.selectedProgram;


            c.data.selectedProgramId =
              response.data.selectedProgram.sys_id;

          }

        }
      );

    };


  /* =========================================================
     SUBMISSIONS MODAL
     ========================================================= */

  c.submissionModalOpen =
    false;


  c.selectedAssignment =
    null;


  c.submissionData = {

    total: 0,

    submitted: 0,

    review: 0,

    evaluated: 0,

    rows: []

  };


  c.openAssignmentSubmissions =
    function(assignment) {

      if (
        !assignment ||
        !assignment.sys_id
      ) {

        return;

      }


      c.selectedAssignment =
        assignment;


      c.submissionData = {

        total: 0,

        submitted: 0,

        review: 0,

        evaluated: 0,

        rows: []

      };


      c.submissionModalOpen =
        true;


      c.server.get({

        action:
          'load_submissions',

        trainer:
          c.currentTrainerId,

        assignment:
          assignment.sys_id

      }).then(
        function(response) {

          if (
            response &&
            response.data &&
            response.data.submissionData
          ) {

            c.submissionData =
              response.data.submissionData;

          }

        }
      );

    };


  c.closeSubmissionModal =
    function() {

      c.submissionModalOpen =
        false;

      c.selectedAssignment =
        null;

    };


  /* =========================================================
     EVALUATION
     ========================================================= */

  c.evaluationModalOpen =
    false;


  c.savingEvaluation =
    false;


  c.evaluationError =
    '';


  c.evaluation =
    {};


  c.openEvaluation =
    function(submission) {

      c.evaluationError =
        '';


      c.evaluation = {

        sys_id:
          submission.sys_id,

        studentName:
          submission.studentName,

        studentId:
          submission.studentId,

        initials:
          submission.initials,

        status:
          submission.status == 'Not Submitted'
            ? 'Submitted'
            : submission.status,

        score:
          submission.score,

        feedback:
          submission.feedback || '',

        submissionLink:
          submission.submissionLink || ''

      };


      c.evaluationModalOpen =
        true;

    };


  c.closeEvaluation =
    function() {

      c.evaluationModalOpen =
        false;

      c.evaluationError =
        '';

    };


  c.saveEvaluation =
    function() {

      c.evaluationError =
        '';


      if (
        !c.evaluation.sys_id
      ) {

        c.evaluationError =
          'Submission record is missing.';

        return;

      }


      c.savingEvaluation =
        true;


      c.server.get({

        action:
          'save_evaluation',

        trainer:
          c.currentTrainerId,

        submission:
          c.evaluation.sys_id,

        status:
          c.evaluation.status,

        score:
          c.evaluation.score,

        feedback:
          c.evaluation.feedback || ''

      }).then(
        function(response) {

          c.savingEvaluation =
            false;


          if (
            response &&
            response.data &&
            response.data.evaluationSuccess
          ) {

            c.evaluationModalOpen =
              false;


            c.reloadSubmissions();

          } else {

            c.evaluationError =
              response.data.evaluationMessage ||
              'Unable to save evaluation.';

          }

        }
      );

    };


  /* =========================================================
     RELOAD SUBMISSIONS
     ========================================================= */

  c.reloadSubmissions =
    function() {

      if (
        !c.selectedAssignment
      ) {

        return;

      }


      c.server.get({

        action:
          'load_submissions',

        trainer:
          c.currentTrainerId,

        assignment:
          c.selectedAssignment.sys_id

      }).then(
        function(response) {

          if (
            response &&
            response.data &&
            response.data.submissionData
          ) {

            c.submissionData =
              response.data.submissionData;

          }

        }
      );

    };


  /* =========================================================
     REFRESH PAGE
     ========================================================= */

  c.refresh =
    function() {

      c.server.update();

    };

};

sp_widget.css:
/* ========================================================= 
   CAMPUS360 TRAINER - MY TRAINING 
   FULL VIEW / FULL SCREEN / DASHBOARD MATCH 
   DARK PURPLE SIDEBAR - STUDENT PAGE STYLE
   ========================================================= */ 
 

/* ========================================================= 
   GLOBAL PAGE RESET 
   ========================================================= */ 
 
html, 
body { 
 
  width: 100% !important; 
 
  min-width: 100% !important; 
 
  height: 100% !important; 
 
  min-height: 100% !important; 
 
  margin: 0 !important; 
 
  padding: 0 !important; 
 
  overflow: hidden !important; 
 
} 
 
 
body { 
 
  background: #f3f6fb !important; 
 
} 
 
 
/* ========================================================= 
   SERVICE NOW OUTER WRAPPER RESET 
   ========================================================= */ 
 
.container, 
.container-fluid, 
.row, 
[class*="col-"], 
.well, 
.panel, 
.panel-body { 
 
  box-sizing: border-box; 
 
} 
 
 
/* 
   These rules ensure the widget doesn't remain constrained 
   inside the normal portal content width. 
*/ 
 
.container:has(.campus360-trainer-app), 
.container-fluid:has(.campus360-trainer-app), 
.row:has(.campus360-trainer-app), 
[class*="col-"]:has(.campus360-trainer-app), 
.well:has(.campus360-trainer-app), 
.panel:has(.campus360-trainer-app) { 
 
  width: 100% !important; 
 
  max-width: none !important; 
 
  margin: 0 !important; 
 
  padding: 0 !important; 
 
  border: 0 !important; 
 
  background: transparent !important; 
 
  box-shadow: none !important; 
 
} 
 
 
/* ========================================================= 
   FULL SCREEN CAMPUS360 APPLICATION 
   ========================================================= */ 
 
/* 
   IMPORTANT: 
   The ServiceNow "System Administrator" header is outside 
   the widget. This full-screen fixed layer places Campus360 
   above the complete portal viewport. 
 
   This is intentionally NOT position: relative. 
*/ 
 
.campus360-trainer-app { 
 
  position: fixed !important; 
 
  top: 0 !important; 
 
  left: 0 !important; 
 
  right: 0 !important; 
 
  bottom: 0 !important; 
 
  width: 100vw !important; 
 
  height: 100vh !important; 
 
  max-width: 100vw !important; 
 
  max-height: 100vh !important; 
 
  min-width: 100vw !important; 
 
  min-height: 100vh !important; 
 
  margin: 0 !important; 
 
  padding: 0 !important; 
 
  z-index: 2147483647 !important; 
 
  display: flex !important; 
 
  flex-direction: row !important; 
 
  overflow: hidden !important; 
 
  background: 
    radial-gradient( 
      circle at 8% 7%, 
      rgba(239,231,255,.48), 
      transparent 25% 
    ), 
    radial-gradient( 
      circle at 95% 10%, 
      rgba(232,247,255,.52), 
      transparent 25% 
    ), 
    #f3f6fb; 
 
  color: #14213b; 
 
  font-family: 
    "Inter", 
    "Segoe UI", 
    Arial, 
    sans-serif; 
 
  -webkit-font-smoothing: antialiased; 
 
  isolation: isolate; 
 
} 
 
 
.campus360-trainer-app, 
.campus360-trainer-app * { 
 
  box-sizing: border-box; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR 
   DARK PURPLE - SAME STYLE AS STUDENT PAGES
   ========================================================= */ 
 
.campus360-trainer-sidebar { 
 
  position: relative !important; 
 
  top: 0 !important; 
 
  left: 0 !important; 
 
  width: 264px !important; 
 
  min-width: 264px !important; 
 
  max-width: 264px !important; 
 
  height: 100vh !important; 
 
  min-height: 100vh !important; 
 
  max-height: 100vh !important; 
 
  z-index: 20; 
 
  flex: 0 0 264px; 
 
  display: flex; 
 
  flex-direction: column; 
 
  overflow: hidden; 
 
  background: 
    linear-gradient( 
      180deg, 
      #130d2f 0%, 
      #160d38 48%, 
      #100a29 100% 
    ) !important; 
 
  border-right: 
    1px solid 
    #2d2157 !important; 
 
  box-shadow: 
    5px 0 18px 
    rgba(10,7,30,.18); 
 
  transition: 
    width .25s ease, 
    min-width .25s ease, 
    flex-basis .25s ease; 
 
} 
 
 
/* ========================================================= 
   BRAND 
   DARK PURPLE
   ========================================================= */ 
 
.trainer-brand { 
 
  width: 100%; 
 
  height: 99px; 
 
  min-height: 99px; 
 
  padding: 
    0 
    15px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 13px; 
 
  flex-shrink: 0; 
 
  background: 
    linear-gradient( 
      135deg, 
      #170e38, 
      #1c1045 
    ) !important; 
 
  border-bottom: 
    1px solid 
    #2d2157 !important; 
 
} 
 
 
.trainer-brand-mark { 
 
  width: 49px; 
 
  height: 49px; 
 
  flex: 0 0 49px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 14px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7c3aed, 
      #8b3ff2 
    ) !important; 
 
  color: #ffffff; 
 
  font-size: 23px; 
 
  box-shadow: 
    0 8px 19px 
    rgba(124,58,237,.28); 
 
} 
 
 
.trainer-brand-text { 
 
  min-width: 0; 
 
} 
 
 
.trainer-brand-text strong { 
 
  display: block; 
 
  color: #ffffff !important; 
 
  font-size: 20px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
} 
 
 
.trainer-brand-text span { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #b9abd8 !important; 
 
  font-size: 10px; 
 
  line-height: 1; 
 
  font-weight: 900; 
 
  letter-spacing: 1.25px; 
 
} 
 
 
/* ========================================================= 
   PROFILE 
   DARK PURPLE
   ========================================================= */ 
 
.trainer-profile-mini { 
 
  margin: 
    18px 
    7px 
    13px; 
 
  min-height: 70px; 
 
  padding: 
    11px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 10px; 
 
  flex-shrink: 0; 
 
  text-decoration: none !important; 
 
  background: 
    linear-gradient( 
      135deg, 
      #211342, 
      #29164f 
    ) !important; 
 
  border: 
    1px solid 
    #4b3475 !important; 
 
  border-radius: 13px; 
 
} 
 
 
.trainer-profile-mini:hover { 
 
  background: 
    linear-gradient( 
      135deg, 
      #29174f, 
      #321d5d 
    ) !important; 
 
  border-color: #60458e !important; 
 
} 
 
 
.trainer-avatar { 
 
  width: 44px; 
 
  height: 44px; 
 
  flex: 0 0 44px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 12px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7c3aed, 
      #8b3ff2 
    ) !important; 
 
  color: #ffffff; 
 
  font-size: 12px; 
 
  font-weight: 950; 
 
  box-shadow: 
    0 5px 14px 
    rgba(124,58,237,.20); 
 
} 
 
 
.trainer-profile-info { 
 
  min-width: 0; 
 
  flex: 1; 
 
} 
 
 
.trainer-profile-info strong { 
 
  display: block; 
 
  overflow: hidden; 
 
  color: #ffffff !important; 
 
  font-size: 12px; 
 
  line-height: 1.2; 
 
  font-weight: 950; 
 
  white-space: nowrap; 
 
  text-overflow: ellipsis; 
 
} 
 
 
.trainer-profile-info span { 
 
  display: block; 
 
  margin-top: 3px; 
 
  color: #b9abd8 !important; 
 
  font-size: 9px; 
 
  font-weight: 800; 
 
} 
 
 
.trainer-profile-arrow { 
 
  color: #a99bc7 !important; 
 
  font-size: 19px; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR NAV 
   DARK PURPLE - STUDENT PAGE STYLE
   ========================================================= */ 
 
.trainer-nav { 
 
  flex: 1 1 auto; 
 
  min-height: 0; 
 
  overflow-y: auto; 
 
  overflow-x: hidden; 
 
  padding: 
    0 
    5px 
    18px; 
 
  scrollbar-width: none !important; 
 
  -ms-overflow-style: none !important; 
 
} 
 
 
.trainer-nav::-webkit-scrollbar { 
 
  width: 0 !important; 
 
  height: 0 !important; 
 
} 
 
 
.trainer-nav::-webkit-scrollbar-track { 
 
  background: transparent !important; 
 
} 
 
 
.trainer-nav::-webkit-scrollbar-thumb { 
 
  background: transparent !important; 
 
  border-radius: 15px; 
 
} 
 
 
.trainer-nav-label { 
 
  margin: 
    19px 
    7px 
    7px; 
 
  color: #9283b6 !important; 
 
  font-size: 10px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
  letter-spacing: 1.1px; 
 
} 
 
 
.trainer-nav-item { 
 
  position: relative; 
 
  width: 100%; 
 
  min-height: 47px; 
 
  margin: 
    2px 
    0; 
 
  padding: 
    0 
    10px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 10px; 
 
  border-radius: 10px; 
 
  color: #c4b8dc !important; 
 
  background: transparent !important; 
 
  text-decoration: none !important; 
 
  font-size: 13px; 
 
  line-height: 1.25; 
 
  font-weight: 850; 
 
  transition: 
    background .18s ease, 
    color .18s ease, 
    transform .18s ease; 
 
} 
 
 
.trainer-nav-item:hover { 
 
  background: 
    rgba(124,58,237,.18) !important; 
 
  color: #ffffff !important; 
 
  transform: translateX(1px); 
 
} 
 
 
.trainer-nav-item.active { 
 
  background: 
    linear-gradient( 
      90deg, 
      #7c3aed 0%, 
      #8b3ff2 100% 
    ) !important; 
 
  color: #ffffff !important; 
 
  font-weight: 950; 
 
  padding-left: 10px; 
 
  border-left: 
    4px 
    solid 
    #a78bfa !important; 
 
  box-shadow: 
    inset 
    0 
    0 
    0 
    1px 
    rgba(196,181,253,.10), 
 
    0 
    6px 
    16px 
    rgba(124,58,237,.18); 
 
} 
 
 
.trainer-nav-item.active:before { 
 
  display: none !important; 
 
} 
 
 
.trainer-nav-icon { 
 
  width: 28px; 
 
  min-width: 28px; 
 
  height: 28px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  color: #a99ac8 !important; 
 
  font-size: 17px; 
 
} 
 
 
.trainer-nav-item:hover 
.trainer-nav-icon { 
 
  color: #ffffff !important; 
 
} 
 
 
.trainer-nav-item.active 
.trainer-nav-icon { 
 
  color: #ffffff !important; 
 
} 
 
 
.trainer-nav-text { 
 
  min-width: 0; 
 
  flex: 1; 
 
} 
 
 
.trainer-nav-count { 
 
  min-width: 22px; 
 
  height: 22px; 
 
  margin-left: auto; 
 
  padding: 
    0 
    6px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 50%; 
 
  background: #3a2764 !important; 
 
  color: #d9ceef !important; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
.trainer-nav-item.active 
.trainer-nav-count { 
 
  background: rgba(255,255,255,.18) !important; 
 
  color: #ffffff !important; 
 
} 
 
 
.trainer-nav-count.warning { 
 
  background: #5a3511 !important; 
 
  color: #ffd08a !important; 
 
} 
 
 
/* ========================================================= 
   MAIN 
   ========================================================= */ 
 
.campus360-trainer-main { 
 
  position: relative; 
 
  width: calc(100vw - 264px) !important; 
 
  min-width: 0 !important; 
 
  max-width: calc(100vw - 264px) !important; 
 
  height: 100vh !important; 
 
  min-height: 100vh !important; 
 
  max-height: 100vh !important; 
 
  margin: 0 !important; 
 
  padding: 0 !important; 
 
  flex: 1 1 auto; 
 
  overflow-x: hidden !important; 
 
  overflow-y: auto !important; 
 
  background: 
    #f3f6fb; 
 
  transition: 
    width .25s ease, 
    max-width .25s ease; 
 
} 
 
 
/* ========================================================= 
   COLLAPSED SIDEBAR 
   ========================================================= */ 
 
.campus360-trainer-app.sidebar-collapsed 
.campus360-trainer-sidebar { 
 
  width: 76px !important; 
 
  min-width: 76px !important; 
 
  max-width: 76px !important; 
 
  flex-basis: 76px; 
 
} 
 
 
.campus360-trainer-app.sidebar-collapsed 
.campus360-trainer-main { 
 
  width: calc(100vw - 76px) !important; 
 
  max-width: calc(100vw - 76px) !important; 
 
} 
 
 
/* ========================================================= 
   COLLAPSED CONTENT 
   ========================================================= */ 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-brand { 
 
  padding-left: 0; 
 
  padding-right: 0; 
 
  justify-content: center; 
 
} 
 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-brand-text, 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-profile-info, 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-profile-arrow, 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-nav-label, 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-nav-text, 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-nav-count { 
 
  display: none !important; 
 
} 
 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-profile-mini { 
 
  margin-left: 9px; 
 
  margin-right: 9px; 
 
  justify-content: center; 
 
} 
 
 
.campus360-trainer-app.sidebar-collapsed 
.trainer-nav-item { 
 
  justify-content: center; 
 
  padding-left: 0; 
 
  padding-right: 0; 
 
} 
 
 
/* ========================================================= 
   TOPBAR 
   ========================================================= */ 
 
.trainer-topbar { 
 
  position: sticky; 
 
  top: 0; 
 
  left: 0; 
 
  z-index: 100; 
 
  width: 100%; 
 
  height: 74px; 
 
  min-height: 74px; 
 
  padding: 
    0 
    19px 
    0 
    23px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  gap: 20px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #ffffff, 
      #fbfdff 
    ); 
 
  border-bottom: 
    1px solid 
    #dce4ec; 
 
  box-shadow: 
    0 
    2px 
    9px 
    rgba(25,43,60,.035); 
 
} 
 
 
.trainer-topbar-left { 
 
  min-width: 0; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 12px; 
 
} 
 
 
.trainer-menu-button { 
 
  width: 44px; 
 
  height: 44px; 
 
  flex: 0 0 44px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border: 
    1px solid 
    #dce4ec; 
 
  border-radius: 10px; 
 
  background: #ffffff; 
 
  color: #526b82; 
 
  font-size: 18px; 
 
  cursor: pointer; 
 
} 
 
 
.trainer-menu-button:hover { 
 
  background: #f3efff; 
 
  border-color: #d3c6f5; 
 
  color: #6046da; 
 
} 
 
 
.trainer-breadcrumb { 
 
  min-width: 0; 
 
} 
 
 
.trainer-breadcrumb-text { 
 
  display: flex; 
 
  flex-direction: column; 
 
  gap: 4px; 
 
} 
 
 
.trainer-breadcrumb-text span { 
 
  color: #6346db; 
 
  font-size: 9px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
  letter-spacing: 1.7px; 
 
} 
 
 
.trainer-breadcrumb-text strong { 
 
  color: #142039; 
 
  font-size: 17px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   TOP RIGHT 
   ========================================================= */ 
 
.trainer-topbar-right { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 9px; 
 
  flex-shrink: 0; 
 
} 
 
 
.trainer-top-action { 
 
  position: relative; 
 
  width: 42px; 
 
  height: 42px; 
 
  flex: 0 0 42px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border: 
    1px solid 
    #dce4ed; 
 
  border-radius: 10px; 
 
  background: #ffffff; 
 
  color: #536b81; 
 
  font-size: 16px; 
 
  cursor: pointer; 
 
} 
 
 
.trainer-top-action:hover { 
 
  background: #f4f0ff; 
 
  border-color: #d3c7f5; 
 
  color: #6246d8; 
 
} 
 
 
.trainer-notification-button { 
 
  overflow: visible; 
 
} 
 
 
.trainer-notification-button 
.fa-bell { 
 
  color: #f3a600; 
 
  font-size: 18px; 
 
} 
 
 
.trainer-notification-dot { 
 
  position: absolute; 
 
  top: 7px; 
 
  right: 7px; 
 
  width: 8px; 
 
  height: 8px; 
 
  border: 
    2px solid 
    #ffffff; 
 
  border-radius: 50%; 
 
  background: #ef4444; 
 
} 
 
 
.trainer-top-profile { 
 
  min-height: 44px; 
 
  padding-left: 9px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 9px; 
 
  border-left: 
    1px solid 
    #e4e8ee; 
 
  text-decoration: none !important; 
 
} 
 
 
.trainer-top-avatar { 
 
  width: 42px; 
 
  height: 42px; 
 
  flex: 0 0 42px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 11px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #704cf4, 
      #5742d4 
    ); 
 
  color: #ffffff; 
 
  font-size: 10px; 
 
  font-weight: 950; 
 
} 
 
 
.trainer-top-profile-text { 
 
  display: flex; 
 
  flex-direction: column; 
 
} 
 
 
.trainer-top-profile-text strong { 
 
  color: #17233b; 
 
  font-size: 11px; 
 
  font-weight: 950; 
 
} 
 
 
.trainer-top-profile-text span { 
 
  margin-top: 3px; 
 
  color: #768399; 
 
  font-size: 8px; 
 
  font-weight: 800; 
 
} 
 
 
/* ========================================================= 
   PAGE 
   ========================================================= */ 
 
.trainer-training-page { 
 
  width: 100% !important; 
 
  max-width: none !important; 
 
  margin: 0 !important; 
 
  padding: 
    27px 
    31px 
    40px; 
 
  background: 
    radial-gradient( 
      circle at 96% 13%, 
      rgba(232,247,255,.42), 
      transparent 25% 
    ), 
    radial-gradient( 
      circle at 4% 53%, 
      rgba(243,235,255,.42), 
      transparent 27% 
    ), 
    #f3f6fb; 
 
} 
 
 
/* ========================================================= 
   HEADER 
   ========================================================= */ 
 
.training-page-header { 
 
  width: 100%; 
 
  min-height: 104px; 
 
  margin-bottom: 19px; 
 
  display: flex; 
 
  align-items: flex-end; 
 
  justify-content: space-between; 
 
  gap: 20px; 
 
} 
 
 
.trainer-eyebrow { 
 
  display: block; 
 
  margin-bottom: 7px; 
 
  color: #6548dc; 
 
  font-size: 10px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
  letter-spacing: 1.6px; 
 
} 
 
 
.training-page-header h1 { 
 
  margin: 
    0 
    0 
    7px; 
 
  color: #0c1831; 
 
  font-size: 35px; 
 
  line-height: 1.03; 
 
  font-weight: 950; 
 
  letter-spacing: -.5px; 
 
} 
 
 
.training-page-header p { 
 
  margin: 0; 
 
  color: #5d6d83; 
 
  font-size: 13px; 
 
  line-height: 1.55; 
 
  font-weight: 600; 
 
} 
 
 
.training-trainer-badge { 
 
  min-width: 138px; 
 
  padding: 
    13px 
    16px; 
 
  border: 
    1px solid 
    #d9dfeb; 
 
  border-radius: 13px; 
 
  background: #ffffff; 
 
  box-shadow: 
    0 
    5px 
    13px 
    rgba(39,52,73,.04); 
 
} 
 
 
.training-trainer-badge span { 
 
  display: block; 
 
  color: #778398; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  letter-spacing: 1px; 
 
} 
 
 
.training-trainer-badge strong { 
 
  display: block; 
 
  margin-top: 6px; 
 
  color: #6043da; 
 
  font-size: 19px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   SUMMARY CARDS 
   ========================================================= */ 
 
.training-summary-grid { 
 
  width: 100%; 
 
  display: grid; 
 
  grid-template-columns: 
    repeat(4,minmax(0,1fr)); 
 
  gap: 15px; 
 
  margin-bottom: 19px; 
 
} 
 
 
.training-summary-card { 
 
  min-height: 135px; 
 
  padding: 18px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 14px; 
 
  border-radius: 15px; 
 
  box-shadow: 
    0 
    4px 
    12px 
    rgba(35,47,70,.035); 
 
} 
 
 
.training-summary-card.purple { 
 
  background: 
    linear-gradient( 
      135deg, 
      #f0e8ff, 
      #e3d7ff 
    ); 
 
  border: 
    1px 
    solid 
    #d3c2fb; 
 
} 
 
 
.training-summary-card.blue { 
 
  background: 
    linear-gradient( 
      135deg, 
      #eaf7ff, 
      #d9edff 
    ); 
 
  border: 
    1px 
    solid 
    #bddcf4; 
 
} 
 
 
.training-summary-card.green { 
 
  background: 
    linear-gradient( 
      135deg, 
      #eaf9f2, 
      #d7f0e4 
    ); 
 
  border: 
    1px 
    solid 
    #bfe2d0; 
 
} 
 
 
.training-summary-card.orange { 
 
  background: 
    linear-gradient( 
      135deg, 
      #fff3e5, 
      #ffe4c7 
    ); 
 
  border: 
    1px 
    solid 
    #f4d1aa; 
 
} 
 
 
.summary-card-icon { 
 
  width: 51px; 
 
  height: 51px; 
 
  flex: 0 0 51px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 13px; 
 
  background: 
    rgba(255,255,255,.87); 
 
  font-size: 20px; 
 
} 
 
 
.training-summary-card.purple 
.summary-card-icon { 
 
  color: #694ce2; 
 
} 
 
 
.training-summary-card.blue 
.summary-card-icon { 
 
  color: #287cc4; 
 
} 
 
 
.training-summary-card.green 
.summary-card-icon { 
 
  color: #159475; 
 
} 
 
 
.training-summary-card.orange 
.summary-card-icon { 
 
  color: #d27b1f; 
 
} 
 
 
.training-summary-card span { 
 
  display: block; 
 
  color: #627187; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  letter-spacing: 1px; 
 
} 
 
 
.training-summary-card strong { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #15233b; 
 
  font-size: 28px; 
 
  line-height: 1; 
 
  font-weight: 950; 
 
} 
 
 
.training-summary-card small { 
 
  display: block; 
 
  margin-top: 6px; 
 
  color: #617188; 
 
  font-size: 9px; 
 
  font-weight: 700; 
 
} 
 
 
/* ========================================================= 
   TRAINER PANEL 
   ========================================================= */ 
 
.trainer-panel { 
 
  width: 100%; 
 
  margin-bottom: 18px; 
 
  padding: 21px; 
 
  border: 
    1px 
    solid 
    #dce3eb; 
 
  border-radius: 15px; 
 
  background: 
    rgba(255,255,255,.97); 
 
  box-shadow: 
    0 
    5px 
    16px 
    rgba(31,46,69,.045); 
 
} 
 
 
.trainer-panel-heading { 
 
  min-height: 61px; 
 
  padding-bottom: 16px; 
 
  display: flex; 
 
  align-items: flex-start; 
 
  justify-content: space-between; 
 
  gap: 16px; 
 
  border-bottom: 
    1px 
    solid 
    #e6ebf0; 
 
} 
 
 
.trainer-panel-heading 
> div:first-child 
> span { 
 
  display: block; 
 
  margin-bottom: 5px; 
 
  color: #6547db; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
  letter-spacing: 1.5px; 
 
} 
 
 
.trainer-panel-heading h2 { 
 
  margin: 0; 
 
  color: #132039; 
 
  font-size: 22px; 
 
  line-height: 1.15; 
 
  font-weight: 950; 
 
} 
 
 
.panel-description { 
 
  margin: 
    5px 
    0 
    0; 
 
  color: #728197; 
 
  font-size: 10px; 
 
  font-weight: 650; 
 
} 
 
 
.panel-heading-action { 
 
  display: flex; 
 
  align-items: center; 
 
} 
 
 
.panel-link-button { 
 
  padding: 0; 
 
  border: 0; 
 
  background: transparent; 
 
  color: #6145d6; 
 
  font-size: 10px; 
 
  font-weight: 950; 
 
  cursor: pointer; 
 
} 
 
 
/* ========================================================= 
   PROGRAM CARDS 
   ========================================================= */ 
 
.training-program-grid { 
 
  width: 100%; 
 
  display: grid; 
 
  grid-template-columns: 
    repeat(3,minmax(0,1fr)); 
 
  gap: 15px; 
 
  padding-top: 16px; 
 
} 
 
 
.training-program-card { 
 
  position: relative; 
 
  width: 100%; 
 
  min-height: 323px; 
 
  padding: 18px; 
 
  border: 
    1px 
    solid 
    #dbe3ec; 
 
  border-radius: 14px; 
 
  background: #ffffff; 
 
  color: inherit; 
 
  text-align: left; 
 
  font-family: inherit; 
 
  cursor: pointer; 
 
  overflow: hidden; 
 
  box-shadow: 
    0 
    3px 
    11px 
    rgba(34,47,69,.025); 
 
  transition: 
    transform .18s ease, 
    box-shadow .18s ease, 
    border-color .18s ease; 
 
} 
 
 
.training-program-card:nth-child(1) { 
 
  background: 
    linear-gradient( 
      145deg, 
      #ffffff, 
      #faf7ff 60%, 
      #efe7ff 
    ); 
 
  border-color: #d9cdf6; 
 
} 
 
 
.training-program-card:nth-child(2) { 
 
  background: 
    linear-gradient( 
      145deg, 
      #ffffff, 
      #f7fbff 60%, 
      #e7f5ff 
    ); 
 
  border-color: #cde3f2; 
 
} 
 
 
.training-program-card:nth-child(3) { 
 
  background: 
    linear-gradient( 
      145deg, 
      #ffffff, 
      #f8fcfa 60%, 
      #e7f7f1 
    ); 
 
  border-color: #cde6db; 
 
} 
 
 
.training-program-card:nth-child(4) { 
 
  background: 
    linear-gradient( 
      145deg, 
      #ffffff, 
      #fffaf7 60%, 
      #fff0e6 
    ); 
 
  border-color: #efd8ca; 
 
} 
 
 
.training-program-card:nth-child(5) { 
 
  background: 
    linear-gradient( 
      145deg, 
      #ffffff, 
      #fffafa 60%, 
      #ffe9ea 
    ); 
 
  border-color: #efd3d4; 
 
} 
 
 
.training-program-card:nth-child(6) { 
 
  background: 
    linear-gradient( 
      145deg, 
      #ffffff, 
      #fffdf4 60%, 
      #fff7da 
    ); 
 
  border-color: #e8dcaf; 
 
} 
 
 
.training-program-card:hover { 
 
  transform: translateY(-3px); 
 
  box-shadow: 
    0 
    11px 
    23px 
    rgba(53,58,89,.09); 
 
} 
 
 
.training-program-card.selected { 
 
  border: 
    2px 
    solid 
    #6b4ae4; 
 
  box-shadow: 
    0 
    13px 
    27px 
    rgba(100,76,199,.12); 
 
} 
 
 
.training-program-card.selected:before { 
 
  content: ""; 
 
  position: absolute; 
 
  top: 0; 
 
  left: 0; 
 
  right: 0; 
 
  height: 4px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #6949e0, 
      #9b7bef 
    ); 
 
} 
 
 
/* ========================================================= 
   PROGRAM CONTENT 
   ========================================================= */ 
 
.program-card-top { 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
} 
 
 
.program-card-icon { 
 
  width: 46px; 
 
  height: 46px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 12px; 
 
  background: #e9e0ff; 
 
  color: #6849dc; 
 
  font-size: 19px; 
 
} 
 
 
.training-program-card:nth-child(2) 
.program-card-icon { 
 
  background: #dff1ff; 
 
  color: #2777b6; 
 
} 
 
 
.training-program-card:nth-child(3) 
.program-card-icon { 
 
  background: #dff4ed; 
 
  color: #16816d; 
 
