  align-items: center; 
 
  padding: 
    6px 
    10px; 
 
  border-radius: 17px; 
 
  background: #eef1f5; 
 
  color: #647287; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
} 
 
 
.training-program-card:nth-child(1) 
