  color: #6046d0; 
 
} 
 
 
.training-program-card:nth-child(2) 
.program-status { 
 
  background: #e3f3ff; 
 
  color: #387ba8; 
 
} 
 
 
.training-program-card:nth-child(3) 
.program-status { 
 
  background: #e4f7ef; 
 
  color: #298169; 
 
} 
 
 
.program-status.large { 
 
  padding: 
    8px 
    12px; 
 
  font-size: 9px; 
 
} 
 
 
.program-card-id { 
 
  margin-top: 14px; 
 
  color: #6849dc; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
  letter-spacing: .9px; 
 
} 
 
 
.training-program-card h3 { 
 
  margin: 
    6px 
    0 
    9px; 
 
  color: #18233b; 
 
  font-size: 18px; 
 
  line-height: 1.23; 
 
  font-weight: 950; 
 
} 
 
 
.program-skill { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 6px; 
 
  color: #627086; 
 
  font-size: 10px; 
 
  font-weight: 800; 
 
} 
 
 
.program-meta-grid { 
 
  display: grid; 
 
  grid-template-columns: 
    1fr 
    1fr; 
 
  gap: 9px; 
 
  margin-top: 14px; 
 
} 
 
 
.program-meta-grid > div { 
 
  min-height: 51px; 
 
  padding: 10px; 
 
  border: 
    1px 
    solid 
    #dfe5ec; 
 
  border-radius: 9px; 
 
  background: 
    rgba(255,255,255,.75); 
 
} 
 
 
.program-meta-grid span { 
 
  display: block; 
 
  color: #788499; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.program-meta-grid strong { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #1d2942; 
 
  font-size: 14px; 
 
  font-weight: 950; 
 
} 
 
 
.program-progress { 
 
  margin-top: 14px; 
 
} 
 
 
.program-progress-heading { 
 
  display: flex; 
 
  justify-content: space-between; 
 
  margin-bottom: 6px; 
 
} 
 
 
.program-progress-heading span { 
 
  color: #748097; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.program-progress-heading strong { 
 
  color: #6246d4; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
.program-progress-track { 
 
  height: 8px; 
 
  overflow: hidden; 
 
  border-radius: 20px; 
 
  background: #e4e9ef; 
 
} 
 
 
.program-progress-fill { 
 
  height: 100%; 
 
  border-radius: 20px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #704fe1, 
      #a287ef 
    ); 
 
} 
 
 
.program-date { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 6px; 
 
  margin-top: 13px; 
 
  color: #68768c; 
 
  font-size: 8px; 
 
  font-weight: 800; 
 
} 
 
 
.program-open { 
 
  margin-top: 13px; 
 
  padding-top: 11px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  border-top: 
    1px solid 
    rgba(223,227,234,.8); 
 
  color: #5d42d1; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   SELECTED TRAINING 
   ========================================================= */ 
 
.selected-training-panel { 
 
  width: 100%; 
 
  margin-bottom: 18px; 
 
  overflow: hidden; 
 
  border: 
    1px solid 
    #d9e1ea; 
 
  border-radius: 16px; 
 
  background: #ffffff; 
 
  box-shadow: 
    0 
    8px 
    23px 
    rgba(29,45,68,.055); 
 
} 
 
 
.selected-training-header { 
 
  position: relative; 
 
  min-height: 108px; 
 
  padding: 
    21px 
    23px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  gap: 18px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #fbf9ff, 
      #f4faff 
    ); 
 
  border-bottom: 
    1px solid 
    #e6ebf0; 
 
} 
 
 
.selected-training-header:before { 
 
  content: ""; 
 
  position: absolute; 
 
  left: 0; 
 
  top: 0; 
 
  bottom: 0; 
 
  width: 4px; 
 
  background: 
    linear-gradient( 
      180deg, 
      #704fe0, 
      #a58af1 
    ); 
 
} 
 
 
.selected-training-title { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 14px; 
 
} 
 
 
.selected-program-icon { 
 
  width: 55px; 
 
  height: 55px; 
 
  flex: 0 0 55px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 14px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7d60e8, 
      #5e4ad0 
    ); 
 
  color: #ffffff; 
 
  font-size: 22px; 
 
} 
 
 
.selected-program-id { 
 
  display: block; 
 
  color: #6a4bdc; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  letter-spacing: 1px; 
 
} 
 
 
.selected-training-title h2 { 
 
  margin: 
    4px 
    0; 
 
  color: #152039; 
 
  font-size: 25px; 
 
  line-height: 1.08; 
 
  font-weight: 950; 
 
} 
 
 
.selected-training-title p { 
 
  margin: 0; 
 
  color: #647188; 
 
  font-size: 11px; 
 
  font-weight: 700; 
 
} 
 
 
/* ========================================================= 
   SELECTED METRICS 
   ========================================================= */ 
 
.selected-training-metrics { 
 
  display: grid; 
 
  grid-template-columns: 
    repeat(6,minmax(0,1fr)); 
 
  gap: 9px; 
 
  padding: 
    15px 
    21px; 
 
  background: #fafbfd; 
 
  border-bottom: 
    1px solid 
    #e7ecf1; 
 
} 
 
 
.selected-metric { 
 
  min-height: 70px; 
 
  padding: 10px; 
 
  border: 
    1px 
    solid 
    #dce4eb; 
 
  border-radius: 9px; 
 
  background: #ffffff; 
 
} 
 
 
.selected-metric.metric-purple { 
 
  background: #f8f4ff; 
 
  border-top: 3px solid #7c5de7; 
 
} 
 
 
.selected-metric.metric-blue { 
 
  background: #f2faff; 
 
  border-top: 3px solid #59a5d9; 
 
} 
 
 
.selected-metric.metric-orange { 
 
  background: #fff8ef; 
 
  border-top: 3px solid #e5a05e; 
 
} 
 
 
.selected-metric.metric-green { 
 
  background: #f2fbf7; 
 
  border-top: 3px solid #55b08e; 
 
} 
 
 
.selected-metric.metric-red { 
 
  background: #fff5f5; 
 
  border-top: 3px solid #df7d7d; 
 
} 
 
 
.selected-metric span { 
 
  display: block; 
 
  color: #758197; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.selected-metric strong { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #1a2741; 
 
  font-size: 14px; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   TABS 
   ========================================================= */ 
 
.training-tabs { 
 
  min-height: 58px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 3px; 
 
  padding: 
    0 
    19px; 
 
  background: #ffffff; 
 
  border-bottom: 
    1px solid 
    #e1e7ee; 
 
  overflow-x: auto; 
 
} 
 
 
.training-tabs button { 
 
  position: relative; 
 
  min-height: 58px; 
 
  padding: 
    0 
    15px; 
 
  border: 0; 
 
  background: transparent; 
 
  color: #627087; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 7px; 
 
  font-family: inherit; 
 
  font-size: 10px; 
 
  font-weight: 900; 
 
  cursor: pointer; 
 
  white-space: nowrap; 
 
} 
 
 
.training-tabs button.active { 
 
  color: #5940d3; 
 
} 
 
 
.training-tabs button.active:after { 
 
  content: ""; 
 
  position: absolute; 
 
  left: 7px; 
 
  right: 7px; 
 
  bottom: 0; 
 
  height: 3px; 
 
  border-radius: 
    4px 
    4px 
    0 
    0; 
 
  background: 
    linear-gradient( 
      90deg, 
      #6847de, 
      #9b7cee 
    ); 
 
} 
 
 
.training-tabs button b { 
 
  min-width: 20px; 
 
  height: 20px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 20px; 
 
  background: #eee9ff; 
 
  color: #5b43d5; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   TAB CONTENT 
   ========================================================= */ 
 
.training-tab-content { 
 
  width: 100%; 
 
  padding: 
    20px 
    21px 
    24px; 
 
} 
 
 
.overview-grid { 
 
  width: 100%; 
 
  display: grid; 
 
  grid-template-columns: 
    minmax(0,1.35fr) 
    minmax(290px,.9fr); 
 
  gap: 13px; 
 
} 
 
 
.overview-card { 
 
  min-height: 150px; 
 
  padding: 17px; 
 
  border: 
    1px 
    solid 
    #dfe5ec; 
 
  border-radius: 11px; 
 
  background: #fbfcfe; 
 
} 
 
 
.primary-overview { 
 
  position: relative; 
 
  display: flex; 
 
  gap: 13px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #f3eeff, 
      #faf8ff 
    ); 
 
  border-color: #d9cef5; 
 
} 
 
 
.primary-overview:before { 
 
  content: ""; 
 
  position: absolute; 
 
  left: 0; 
 
  top: 0; 
 
  bottom: 0; 
 
  width: 4px; 
 
  background: 
    linear-gradient( 
      180deg, 
      #704fe1, 
      #a88cf0 
    ); 
 
} 
 
 
.overview-icon { 
 
  width: 46px; 
 
  height: 46px; 
 
