  justify-content: center; 
 
  border-radius: 11px; 
 
  font-size: 18px; 
 
} 
 
 
.purple-icon { 
 
  background: #e8ddff; 
 
  color: #6447d8; 
 
} 
 
 
.primary-overview h3 { 
 
  margin: 
    6px 
    0; 
 
  color: #1b2740; 
 
  font-size: 20px; 
 
  line-height: 1.2; 
 
  font-weight: 950; 
 
} 
 
 
.primary-overview p, 
.overview-muted { 
 
  color: #5e6c81; 
 
  font-size: 10px; 
 
  line-height: 1.5; 
 
} 
 
 
.overview-card-heading { 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
} 
 
 
.overview-card-heading span { 
 
  color: #708096; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.overview-card-heading strong { 
 
  color: #5e43d2; 
 
  font-size: 24px; 
 
  font-weight: 950; 
 
} 
 
 
.large-progress-track { 
 
  width: 100%; 
 
  height: 10px; 
 
  margin-top: 17px; 
 
  overflow: hidden; 
 
  border-radius: 20px; 
 
  background: #e4e9ef; 
 
} 
 
 
.large-progress-fill { 
 
  height: 100%; 
 
  border-radius: 20px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #704fe1, 
      #a287ef 
    ); 
 
} 
 
 
.small-outline-button { 
 
  margin-top: 12px; 
 
  padding: 
    8px 
    11px; 
 
  border: 
    1px 
    solid 
    #d3c7f5; 
 
  border-radius: 7px; 
 
  background: #f6f2ff; 
 
  color: #6147d2; 
 
  font-size: 8px; 
 
  font-weight: 900; 
 
  cursor: pointer; 
 
} 
 
 
.date-range { 
 
  display: grid; 
 
  grid-template-columns: 
    1fr 
    auto 
    1fr; 
 
  align-items: center; 
 
  gap: 8px; 
 
  margin-top: 14px; 
 
} 
 
 
.date-range div { 
 
  padding: 10px; 
 
  border: 
    1px 
    solid 
    #e0e5ed; 
 
  border-radius: 8px; 
 
  background: #ffffff; 
 
} 
 
 
.date-range small { 
 
  color: #758197; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
} 
 
 
.date-range strong { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #243149; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   SUB PANEL / TABLES 
   ========================================================= */ 
 
.sub-panel { 
 
  width: 100%; 
 
  margin-top: 13px; 
 
  overflow: hidden; 
 
  border: 
    1px 
    solid 
    #dfe5ec; 
 
  border-radius: 11px; 
 
  background: #ffffff; 
 
} 
 
 
.sub-panel-heading { 
 
  min-height: 61px; 
 
  padding: 
    13px 
    16px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  border-bottom: 
    1px 
    solid 
    #e9edf2; 
 
} 
 
 
.sub-panel-heading h3 { 
 
  margin: 
    4px 
    0 
    0; 
 
  color: #1c2941; 
 
  font-size: 16px; 
 
  font-weight: 950; 
 
} 
 
 
.panel-count { 
 
  width: 28px; 
 
  height: 28px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 9px; 
 
  background: #eee8ff; 
 
  color: #6147d4; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
.training-table-wrap { 
 
  width: 100%; 
 
  overflow-x: auto; 
 
} 
 
 
.training-table { 
 
  width: 100%; 
 
  border-collapse: collapse; 
 
} 
 
 
.training-table th { 
 
  padding: 11px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #f3eeff, 
      #eef8ff 
    ); 
 
  color: #657287; 
 
  border-bottom: 
    1px 
    solid 
    #dfe4ed; 
 
  text-align: left; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .7px; 
 
  text-transform: uppercase; 
 
} 
 
 
.training-table td { 
 
  padding: 11px; 
 
  border-bottom: 
    1px 
    solid 
    #edf1f5; 
 
  color: #536078; 
 
  font-size: 9px; 
 
  font-weight: 700; 
 
} 
 
 
.table-person { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 8px; 
 
} 
 
 
.table-avatar { 
 
  width: 31px; 
 
  height: 31px; 
 
  flex: 0 0 31px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 8px; 
 
  background: #eae3ff; 
 
  color: #6045d2; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
} 
 
 
.table-person strong { 
 
  color: #263249; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
.table-number { 
 
  color: #253047; 
 
  font-size: 10px; 
 
  font-weight: 950; 
 
} 
 
 
.table-progress-wrap { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 7px; 
 
} 
 
 
.table-progress { 
 
  width: 70px; 
 
  height: 6px; 
 
  overflow: hidden; 
 
  border-radius: 20px; 
 
  background: #e4e9ef; 
 
} 
 
 
.table-progress-fill { 
 
  height: 100%; 
 
  border-radius: 20px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #704fe0, 
      #9f81ed 
    ); 
 
} 
 
 
.training-status-pill, 
.assignment-status-pill { 
 
  display: inline-flex; 
 
  align-items: center; 
 
  padding: 
    5px 
    8px; 
 
  border-radius: 16px; 
 
  background: #eee9ff; 
 
  color: #6145d3; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
} 
 
 
/* ========================================================= 
   ATTENDANCE 
   ========================================================= */ 
 
.attendance-header { 
 
  min-height: 84px; 
 
  padding: 
    14px 
    16px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  gap: 15px; 
 
  border-bottom: 
    1px 
    solid 
    #e9edf2; 
 
  background: 
    linear-gradient( 
      90deg, 
      #fbfaff, 
      #f8fcff 
    ); 
 
} 
 
 
.attendance-header 
> div:first-child 
