  border-radius: 7px; 
 
  background: #ffffff; 
 
  color: #33455e; 
 
  font-size: 9px; 
 
  font-weight: 800; 
 
} 
 
 
.primary-training-button { 
 
  height: 35px; 
 
  padding: 
    0 
    12px; 
 
  border: 0; 
 
  border-radius: 7px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #6548df, 
      #8062e8 
    ); 
 
  color: #ffffff; 
 
