  color: #344258; 
 
  font-size: 9px; 
 
} 
 
 
/* ========================================================= 
   ASSIGNMENTS 
   ========================================================= */ 
 
.assignment-section-header { 
 
  min-height: 79px; 
 
  padding: 
    14px 
    16px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  gap: 15px; 
 
  border-bottom: 
    1px 
    solid 
    #e8edf2; 
 
  background: 
    linear-gradient( 
      90deg, 
      #fffaf6, 
      #faf8ff 
    ); 
 
} 
 
 
.assignment-section-header 
> div:first-child 
> span { 
 
  color: #c4744d; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .9px; 
 
} 
 
 
.assignment-section-header h3 { 
 
  margin: 
    4px 
    0; 
 
  color: #202b43; 
 
  font-size: 18px; 
 
  font-weight: 950; 
 
} 
 
 
.assignment-section-header p { 
 
  margin: 0; 
 
  color: #748196; 
 
  font-size: 8px; 
 
} 
 
 
.assignment-header-right { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 8px; 
 
} 
 
 
.create-assignment-button { 
 
  height: 36px; 
 
  padding: 
    0 
    12px; 
 
  border: 0; 
 
  border-radius: 8px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #6a4be0, 
      #8569eb 
    ); 
 
  color: #ffffff; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
  cursor: pointer; 
 
} 
 
 
.assignment-row { 
 
  min-height: 71px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 11px; 
 
  padding: 
    11px 
    16px; 
 
  border-bottom: 
    1px 
    solid 
    #edf1f4; 
 
} 
 
 
.assignment-row.clickable:hover { 
 
  background: #fbfaff; 
 
} 
 
 
.assignment-icon { 
 
  width: 38px; 
 
  height: 38px; 
 
  flex: 0 0 38px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 9px; 
 
  background: #ece4ff; 
 
  color: #6246d2; 
 
  font-size: 14px; 
 
} 
 
 
.assignment-main { 
 
  flex: 1; 
 
  min-width: 0; 
 
  display: flex; 
 
  flex-direction: column; 
 
} 
 
 
.assignment-main strong { 
 
  color: #263249; 
 
  font-size: 10px; 
 
  font-weight: 950; 
 
} 
 
 
.assignment-main span { 
 
  margin-top: 3px; 
 
  color: #6f7d91; 
 
  font-size: 8px; 
 
  font-weight: 700; 
 
} 
 
 
.assignment-main small { 
 
  margin-top: 4px; 
 
  color: #8590a1; 
 
  font-size: 7px; 
 
} 
 
 
.assignment-submissions { 
 
  min-width: 70px; 
 
  text-align: center; 
 
} 
 
 
.assignment-submissions strong { 
 
  display: block; 
 
  color: #253047; 
 
  font-size: 13px; 
 
  font-weight: 950; 
 
} 
 
 
.assignment-submissions span { 
 
  display: block; 
 
  color: #8190a1; 
 
  font-size: 7px; 
 
} 
 
 
.assignment-status-group { 
 
  min-width: 115px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: flex-end; 
 
  gap: 7px; 
 
} 
 
 
.view-submissions-button { 
 
  border: 0; 
 
  background: transparent; 
 
  color: #5d43d0; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  cursor: pointer; 
 
} 
 
 
.empty-create-button { 
 
  margin-top: 12px; 
 
  padding: 
    8px 
    11px; 
 
  border: 
    1px 
    solid 
    #d3c7f5; 
 
  border-radius: 7px; 
 
  background: #f6f2ff; 
 
  color: #6147d2; 
 
  font-size: 8px; 
 
  font-weight: 900; 
 
  cursor: pointer; 
 
} 
 
 
/* ========================================================= 
   EMPTY / FOOTER 
   ========================================================= */ 
 
.trainer-empty, 
.table-empty { 
 
  padding: 
    42px 
    18px; 
 
  text-align: center; 
 
  color: #7b8799; 
 
} 
 
 
.trainer-empty i, 
.table-empty i { 
 
  color: #a08bd1; 
 
  font-size: 27px; 
 
} 
 
 
.trainer-empty h3, 
.table-empty h4 { 
 
  margin: 
    9px 
    0 
    4px; 
 
  color: #2b354b; 
 
  font-size: 15px; 
 
  font-weight: 950; 
 
} 
 
 
.trainer-empty p, 
.table-empty p { 
 
  margin: 0; 
 
  color: #768297; 
 
  font-size: 9px; 
 
} 
 
 
.trainer-page-footer { 
 
  padding: 
    2px 
    2px 
    7px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: space-between; 
 
  color: #7e899c; 
 
  font-size: 8px; 
 
  font-weight: 700; 
 
} 
 
 
/* ========================================================= 
   MODALS 
   ========================================================= */ 
 
.campus360-modal-backdrop { 
 
  position: fixed !important; 
 
  inset: 0 !important; 
 
  z-index: 2147483646 !important; 
 
  padding: 25px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  background: 
    rgba(22,31,49,.48); 
 
} 
 
 
.campus360-modal { 
 
  width: min(780px,95vw); 
 
  max-height: 91vh; 
 
  display: flex; 
 
  flex-direction: column; 
 
  overflow: hidden; 
 
  border-radius: 17px; 
 
  background: #ffffff; 
 
  border: 
    1px solid 
    #e0dfea; 
 
  box-shadow: 
    0 
    26px 
    60px 
    rgba(31,35,68,.25); 
 
} 
 
 
.assignment-modal { 
 
  width: min(760px,95vw); 
 
} 
 
 
.submissions-modal { 
 
  width: min(950px,96vw); 
 
} 
 
 
.evaluation-modal { 
 
  width: min(600px,95vw); 
 
} 
 
 
.modal-header { 
 
  min-height: 78px; 
 
  padding: 
    17px 
    20px; 
 
  display: flex; 
 
  align-items: flex-start; 
 
  justify-content: space-between; 
 
  gap: 14px; 
 
  border-bottom: 
    1px 
    solid 
    #e8ecf1; 
 
  background: 
    linear-gradient( 
      135deg, 
      #fbf9ff, 
      #f3faff 
    ); 
 
} 
 
 
.modal-header span { 
 
  color: #6c4dde; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  letter-spacing: 1px; 
 
} 
 
 
.modal-header h2 { 
 
  margin: 
    4px 
    0; 
 
  color: #202a42; 
 
  font-size: 21px; 
 
  font-weight: 950; 
 
} 
 
 
.modal-header p { 
 
  margin: 0; 
 
  color: #788499; 
 
  font-size: 9px; 
 
} 
 
 
.modal-close { 
 
  width: 34px; 
 
  height: 34px; 
 
  border: 
    1px 
    solid 
    #dbe2ea; 
 
  border-radius: 8px; 
 
  background: #ffffff; 
 
  color: #68768b; 
 
  cursor: pointer; 
 
} 
 
 
.modal-body { 
 
  flex: 1; 
 
  min-height: 0; 
 
  overflow-y: auto; 
 
  padding: 
    19px 
    20px; 
 
} 
 
 
.modal-footer { 
 
  min-height: 62px; 
 
  padding: 
    11px 
    20px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: flex-end; 
 
  gap: 8px; 
 
  border-top: 
    1px 
    solid 
    #e7ebf0; 
 
  background: #fafbfd; 
 
} 
 
 
/* ========================================================= 
   FORM 
   ========================================================= */ 
 
.form-group { 
 
  margin-bottom: 13px; 
 
} 
 
 
.form-group label { 
 
  display: block; 
 
  margin-bottom: 6px; 
 
  color: #637087; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.form-group input, 
.form-group select, 
.form-group textarea { 
 
  width: 100%; 
 
  border: 
    1px 
    solid 
    #d7e0e9; 
 
  border-radius: 8px; 
 
  background: #ffffff; 
 
  color: #27344d; 
 
  font-family: inherit; 
 
  font-size: 10px; 
 
  font-weight: 700; 
 
  outline: none; 
 
} 
 
 
.form-group input, 
.form-group select { 
 
  height: 37px; 
 
  padding: 
    0 
    9px; 
 
} 
 
 
.form-group textarea { 
 
  padding: 9px; 
 
  resize: vertical; 
 
  line-height: 1.5; 
 
} 
 
 
.form-group input:focus, 
.form-group select:focus, 
.form-group textarea:focus { 
 
  border-color: #947ced; 
 
  box-shadow: 
    0 
    0 
    0 
    3px 
    rgba(112,80,220,.09); 
 
} 
 
 
.form-row { 
 
  display: grid; 
 
  grid-template-columns: 
    1fr 
    1fr; 
 
  gap: 10px; 
 
} 
 
 
.form-help { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #8390a2; 
 
  font-size: 7px; 
 
} 
 
 
.readonly-training-field { 
 
  min-height: 55px; 
 
  padding: 9px; 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 9px; 
 
  border: 
    1px 
    solid 
    #dcd4f1; 
 
  border-radius: 9px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #f7f3ff, 
      #f3faff 
    ); 
 
} 
 
 
.readonly-training-field > i { 
 
  width: 31px; 
 
  height: 31px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 7px; 
 
  background: #e8ddff; 
 
  color: #6448d4; 
 
} 
 
 
.readonly-training-field strong { 
 
  display: block; 
 
  color: #29344b; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
.readonly-training-field span { 
 
  display: block; 
 
  margin-top: 2px; 
 
  color: #7a879b; 
 
  font-size: 7px; 
 
} 
 
 
/* ========================================================= 
   BUTTONS 
   ========================================================= */ 
 
.modal-secondary-button, 
.modal-draft-button, 
.modal-primary-button { 
 
  height: 36px; 
 
  padding: 
    0 
    12px; 
 
  border-radius: 8px; 
 
  font-family: inherit; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
  cursor: pointer; 
 
} 
 
 
.modal-secondary-button { 
 
  border: 
    1px 
    solid 
    #d8e0e8; 
 
  background: #ffffff; 
 
  color: #617086; 
 
} 
 
 
.modal-draft-button { 
 
  border: 
    1px 
    solid 
    #d8cdf6; 
 
  background: #f5f0ff; 
 
  color: #6146d4; 
 
} 
 
 
.modal-primary-button { 
 
  border: 0; 
 
  background: 
    linear-gradient( 
      135deg, 
      #6748df, 
      #8064eb 
    ); 
 
  color: #ffffff; 
 
} 
 
 
/* ========================================================= 
   SUBMISSION SUMMARY 
   ========================================================= */ 
 
.submission-summary-grid { 
 
  display: grid; 
 
  grid-template-columns: 
    repeat(4,1fr); 
 
  gap: 9px; 
 
  margin-bottom: 14px; 
 
} 
 
 
.submission-summary-card { 
 
  min-height: 65px; 
 
  padding: 10px; 
 
  border: 
    1px 
    solid 
    #dde3eb; 
 
  border-radius: 9px; 
 
  background: #fafbfd; 
 
} 
 
 
.submission-summary-card span { 
 
  display: block; 
 
  color: #778499; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.submission-summary-card strong { 
 
  display: block; 
 
  margin-top: 5px; 
 
  color: #253148; 
 
  font-size: 20px; 
 
  font-weight: 950; 
 
} 
 
 
.evaluate-button { 
 
  height: 29px; 
 
  padding: 
    0 
    8px; 
 
  border: 
    1px 
    solid 
    #d5caf5; 
 
  border-radius: 7px; 
 
  background: #f4efff; 
 
  color: #5f45d0; 
 
  font-size: 8px; 
 
  font-weight: 950; 
 
  cursor: pointer; 
 
} 
 
 
/* ========================================================= 
   EVALUATION 
   ========================================================= */ 
 
.evaluation-student-card { 
 
  display: flex; 
 
  align-items: center; 
 
  gap: 9px; 
 
  margin-bottom: 14px; 
 
  padding: 10px; 
 
  border: 
    1px 
    solid 
    #ded9eb; 
 
  border-radius: 9px; 
 
  background: #faf8ff; 
 
} 
 
 
.evaluation-avatar { 
 
  width: 37px; 
 
  height: 37px; 
 
  display: flex; 
 
  align-items: center; 
 
  justify-content: center; 
 
  border-radius: 9px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7b61e4, 
      #5f4bcf 
    ); 
 
  color: #ffffff; 
 
  font-size: 9px; 
 
  font-weight: 950; 
 
} 
 
 
.evaluation-student-card strong { 
 
  display: block; 
 
  color: #27334a; 
 
  font-size: 10px; 
 
  font-weight: 950; 
 
} 
 
 
.evaluation-student-card span { 
 
  display: block; 
 
  margin-top: 2px; 
 
  color: #79869a; 
 
  font-size: 7px; 
 
} 
 
 
.submission-link-card { 
 
  margin-bottom: 14px; 
 
  padding: 10px; 
 
  border: 
    1px 
    solid 
    #d0e3ef; 
 
  border-radius: 9px; 
 
  background: #f2faff; 
 
} 
 
 
.submission-link-card > span { 
 
  display: block; 
 
  margin-bottom: 5px; 
 
  color: #61758b; 
 
  font-size: 7px; 
 
  font-weight: 950; 
 
  letter-spacing: .8px; 
 
} 
 
 
.submission-link-card a { 
 
  color: #357fac; 
 
  font-size: 8px; 
 
  font-weight: 700; 
 
  word-break: break-all; 
 
} 
 
 
/* ========================================================= 
   DESKTOP HEIGHT / WIDTH POLISH 
   ========================================================= */ 
 
@media (min-width: 1500px) { 
 
  .trainer-training-page { 
 
    padding-left: 34px; 
 
    padding-right: 34px; 
 
  } 
 
 
  .training-program-card { 
 
    min-height: 335px; 
 
  } 
 
} 
 
 
/* ========================================================= 
   TABLET 
   ========================================================= */ 
 
@media (max-width: 1200px) { 
 
  .training-summary-grid { 
 
    grid-template-columns: 
      repeat( 
        2, 
        minmax(0,1fr) 
      ); 
 
  } 
 
 
  .training-program-grid { 
 
    grid-template-columns: 
      repeat( 
        2, 
        minmax(0,1fr) 
      ); 
 
  } 
 
 
  .selected-training-metrics { 
 
    grid-template-columns: 
      repeat( 
        3, 
        minmax(110px,1fr) 
      ); 
 
  } 
 
} 
 
 
/* ========================================================= 
   MOBILE 
   ========================================================= */ 
 
@media (max-width: 900px) { 
 
  .campus360-trainer-sidebar { 
 
    position: fixed !important; 
 
    left: 0 !important; 
 
    top: 0 !important; 
 
    transform: 
      translateX(-100%); 
 
    width: 264px !important; 
 
    min-width: 264px !important; 
 
    max-width: 264px !important; 
 
    transition: 
      transform .25s ease; 
 
    box-shadow: 
      10px 
      0 
      30px 
      rgba(10,7,30,.30); 
 
    background: 
      linear-gradient( 
        180deg, 
        #130d2f 0%, 
        #160d38 48%, 
        #100a29 100% 
      ) !important; 
 
    border-right: 
      1px 
      solid 
      #2d2157 !important; 
 
  } 
 
 
  .campus360-trainer-app:not(.sidebar-collapsed) 
  .campus360-trainer-sidebar { 
 
    transform: 
      translateX(0); 
 
  } 
 
 
  .campus360-trainer-main, 
  .campus360-trainer-app.sidebar-collapsed 
  .campus360-trainer-main { 
 
    width: 100% !important; 
 
    max-width: 100% !important; 
 
    margin: 0 !important; 
 
  } 
 
 
  .training-program-grid { 
 
    grid-template-columns: 1fr; 
 
  } 
 
 
  .overview-grid { 
 
    grid-template-columns: 1fr; 
 
  } 
 
 
  .training-page-header { 
 
    flex-direction: column; 
 
    align-items: flex-start; 
 
  } 
 
 
  .training-trainer-badge { 
 
    width: 100%; 
 
  } 
 
 
  .selected-training-metrics { 
 
    grid-template-columns: 
      repeat( 
        2, 
        minmax(110px,1fr) 
      ); 
 
  } 
 
 
  .attendance-header { 
 
    flex-direction: column; 
 
    align-items: flex-start; 
 
  } 
 
 
  .attendance-actions { 
 
    width: 100%; 
 
  } 
 
} 
 
 
/* ========================================================= 
   SMALL MOBILE 
   ========================================================= */ 
 
@media (max-width: 650px) { 
 
  .trainer-topbar { 
 
    height: 64px; 
 
    min-height: 64px; 
 
    padding: 
      0 
      10px; 
 
  } 
 
 
  .trainer-top-action, 
  .trainer-menu-button { 
 
    width: 38px; 
 
    height: 38px; 
 
    flex-basis: 38px; 
 
  } 
 
 
  .trainer-top-profile-text { 
 
    display: none; 
 
  } 
 
 
  .trainer-top-profile { 
 
    padding-left: 5px; 
 
  } 
 
 
  .trainer-training-page { 
 
    padding: 
      17px 
      11px 
      30px; 
 
  } 
 
 
  .training-page-header h1 { 
 
    font-size: 28px; 
 
  } 
 
 
  .training-summary-grid { 
 
    grid-template-columns: 1fr; 
 
  } 
 
 
  .selected-training-title { 
 
    align-items: flex-start; 
 
  } 
 
 
  .selected-training-title h2 { 
 
    font-size: 21px; 
 
  } 
 
 
  .selected-training-metrics { 
 
    grid-template-columns: 
      1fr 
      1fr; 
 
  } 
 
 
  .assignment-section-header { 
 
    flex-direction: column; 
 
    align-items: flex-start; 
 
  } 
 
 
  .assignment-header-right { 
 
    width: 100%; 
 
    justify-content: space-between; 
 
  } 
 
 
  .assignment-row { 
 
    flex-wrap: wrap; 
 
  } 
 
 
  .assignment-submissions { 
 
    margin-left: 49px; 
 
  } 
 
 
  .assignment-status-group { 
 
    width: 100%; 
 
    margin-left: 49px; 
 
    justify-content: flex-start; 
 
  } 
 
 
  .form-row { 
 
    grid-template-columns: 1fr; 
 
  } 
 
 
  .submission-summary-grid { 
 
    grid-template-columns: 
      1fr 
      1fr; 
 
  } 
 
} 
 
 
/* ========================================================= 
   VERY SMALL MOBILE 
   ========================================================= */ 
 
@media (max-width: 450px) { 
 
  .trainer-training-page { 
 
    padding: 
      14px 
      9px 
      25px; 
 
  } 
 
 
  .selected-training-metrics { 
 
    grid-template-columns: 1fr; 
 
  } 
 
 
  .submission-summary-grid { 
 
    grid-template-columns: 1fr; 
 
  } 
 
}

sp_widget.script:
(function() {

  data.error = '';
  data.loaded = false;

  data.programs = [];
  data.selectedProgram = null;
  data.selectedProgramId = '';


  /* =========================================================
     CURRENT TRAINER
     ========================================================= */

  var requestedTrainerId =
    String(
      $sp.getParameter('trainer') || ''
    ).trim();


  var trainerGR =
    new GlideRecord(
      'x_snc_campus360_trainer_master'
    );


  if (requestedTrainerId) {

    trainerGR.addQuery(
      'trainer_id',
      requestedTrainerId
    );

  } else {

    trainerGR.orderBy(
      'trainer_id'
    );

  }


  trainerGR.setLimit(1);
  trainerGR.query();


  if (!trainerGR.next()) {

    data.trainer = {

      id: '',

      name: 'Trainer',

      initials: 'TR'

    };


    data.metrics = {

      trainingPrograms: 0,

      students: 0,

      averageProgress: 0,

      assignments: 0

    };


    data.loaded = true;

    return;

  }


  var trainerSysId =
    trainerGR.getUniqueValue();


  var trainerId =
    trainerGR.getValue(
      'trainer_id'
    ) || '';


  var trainerName =
    trainerGR.getValue(
      'trainer_name'
    ) || 'Trainer';


  data.trainer = {

    sys_id:
      trainerSysId,

    id:
      trainerId,

    name:
      trainerName,

    initials:
      getInitials(
        trainerName
      )

  };


  /* =========================================================
     ACTIONS
     ========================================================= */

  if (
    input &&
    input.action == 'create_assignment'
  ) {

    createAssignment();

    data.loaded = true;

    return;

  }


  if (
    input &&
    input.action == 'load_submissions'
  ) {

    loadSubmissions();

    data.loaded = true;

    return;

  }


  if (
    input &&
    input.action == 'save_evaluation'
  ) {

    saveEvaluation();

    data.loaded = true;

    return;

  }


  if (
    input &&
    input.action == 'load_attendance'
  ) {

    loadAttendance();

    data.loaded = true;

    return;

  }


  if (
    input &&
    input.action == 'save_attendance'
  ) {

    saveAttendance();

    data.loaded = true;

    return;

  }


  if (
    input &&
    input.action == 'load_program'
  ) {

    loadSelectedProgram();

    data.loaded = true;

    return;

  }


  /* =========================================================
     NORMAL LOAD
     ========================================================= */

  loadDashboard();

  data.loaded = true;


  /* =========================================================
     LOAD DASHBOARD
     ========================================================= */

  function loadDashboard() {

    var totalStudents = 0;

    var totalProgress = 0;

    var progressCount = 0;

    var totalAssignments = 0;


    var programGR =
      new GlideRecord(
        'x_snc_campus360_training_program'
      );


    programGR.addQuery(
      'trainer',
      trainerSysId
    );


    programGR.orderBy(
      'start_date'
    );


    programGR.query();


    while (
      programGR.next()
    ) {

      var programSysId =
        programGR.getUniqueValue();


      var enrollment =
        getEnrollmentData(
          programSysId
        );


      var assignments =
        getAssignments(
          programSysId
        );


      var programProgress = 0;


      if (
        enrollment.progressCount > 0
      ) {

        programProgress =
          Math.round(
            enrollment.totalProgress /
            enrollment.progressCount
          );

      }


      totalStudents +=
        enrollment.studentCount;


      totalProgress +=
        enrollment.totalProgress;


      progressCount +=
        enrollment.progressCount;


      totalAssignments +=
        assignments.length;


      data.programs.push({

        sys_id:
          programSysId,

        id:
          programGR.getValue(
            'training_id'
          ) || '',

        name:
          programGR.getValue(
            'training_name'
          ) || '',

        skillArea:
          programGR.getValue(
            'skill_area'
          ) || '',

        batch:
          programGR.getValue(
            'batch'
          ) || '',

        startDate:
          formatDate(
            programGR.getValue(
              'start_date'
            )
          ),

        endDate:
          formatDate(
            programGR.getValue(
              'end_date'
            )
          ),

        capacity:
          parseInt(
            programGR.getValue(
              'capacity'
            ),
            10
          ) || 0,

        status:
          programGR.getValue(
            'status'
          ) || '',

        students:
          enrollment.studentCount,

        progress:
          programProgress,

        assignments:
          assignments.length

      });

    }


    data.metrics = {

      trainingPrograms:
        data.programs.length,

      students:
        totalStudents,

      averageProgress:
        progressCount > 0
          ? Math.round(
              totalProgress /
              progressCount
            )
          : 0,

      assignments:
        totalAssignments

    };


    /*
     * Automatically open the first training.
     */

    if (
      data.programs.length > 0
    ) {

      var firstProgram =
        data.programs[0];


      data.selectedProgram =
        getProgramDetail(
          firstProgram.sys_id,
          firstProgram.startDate
        );


      if (
        data.selectedProgram
      ) {

        data.selectedProgramId =
          data.selectedProgram.sys_id;

        data.attendanceDate =
          firstProgram.startDate;

      }

    }

  }


  /* =========================================================
     LOAD SELECTED PROGRAM
     ========================================================= */

  function loadSelectedProgram() {

    var programSysId =
      String(
        input.training || ''
      ).trim();


    var attendanceDate =
      normalizeDate(
        input.date
      );


    if (!programSysId) {

      data.error =
        'Training program is missing.';

      return;

    }


    if (!attendanceDate) {

      var tempGR =
        new GlideRecord(
          'x_snc_campus360_training_program'
        );


      tempGR.addQuery(
        'sys_id',
        programSysId
      );


      tempGR.addQuery(
        'trainer',
        trainerSysId
      );


      tempGR.setLimit(1);
      tempGR.query();


      if (
        tempGR.next()
      ) {

        attendanceDate =
          formatDate(
            tempGR.getValue(
              'start_date'
            )
          );

      }

    }


    data.selectedProgram =
      getProgramDetail(
        programSysId,
        attendanceDate
      );


    if (
      data.selectedProgram
    ) {

      data.selectedProgramId =
        data.selectedProgram.sys_id;

      data.attendanceDate =
        attendanceDate;

    }

  }


  /* =========================================================
     PROGRAM DETAIL
     ========================================================= */

  function getProgramDetail(
    programSysId,
    attendanceDate
  ) {

    var gr =
      new GlideRecord(
        'x_snc_campus360_training_program'
      );


    gr.addQuery(
      'sys_id',
      programSysId
    );


    gr.addQuery(
      'trainer',
      trainerSysId
    );


    gr.setLimit(1);
    gr.query();


    if (!gr.next()) {

      return null;

    }


    var startDate =
      formatDate(
        gr.getValue(
          'start_date'
        )
      );


    var endDate =
      formatDate(
        gr.getValue(
          'end_date'
        )
      );


    var enrollment =
      getEnrollmentData(
        programSysId
      );


    var assignments =
      getAssignments(
        programSysId
      );


    var progress = 0;


    if (
      enrollment.progressCount > 0
    ) {

      progress =
        Math.round(
          enrollment.totalProgress /
          enrollment.progressCount
        );

    }


    var selectedDate =
      normalizeDate(
        attendanceDate
      );


    if (!selectedDate) {

      selectedDate =
        startDate;

    }


    var attendanceRows = [];


    if (
      isDateInsideRange(
        selectedDate,
        startDate,
        endDate
      )
    ) {

      attendanceRows =
        buildAttendanceRows(
          programSysId,
          selectedDate,
          enrollment.students
        );

    }


    return {

      sys_id:
        programSysId,

      id:
        gr.getValue(
          'training_id'
        ) || '',

      name:
        gr.getValue(
          'training_name'
        ) || '',

      skillArea:
        gr.getValue(
          'skill_area'
        ) || '',

      batch:
        gr.getValue(
          'batch'
        ) || '',

      startDate:
        startDate,

      endDate:
        endDate,

      capacity:
        parseInt(
          gr.getValue(
            'capacity'
          ),
          10
        ) || 0,

      status:
        gr.getValue(
          'status'
        ) || '',

      students:
        enrollment.studentCount,

      progress:
        progress,

      assignments:
        assignments.length,

      studentList:
        enrollment.students,

      assignmentList:
        assignments,

      attendanceRows:
        attendanceRows

    };

  }


  /* =========================================================
     CREATE ASSIGNMENT
     ========================================================= */

  function createAssignment() {

    var programSysId =
      String(
        input.training || ''
      ).trim();


    var name =
      String(
        input.name || ''
      ).trim();


    var type =
      String(
        input.assignmentType ||
        'Coding'
      ).trim();


    var description =
      String(
        input.description || ''
      ).trim();


    var resourceLink =
      String(
        input.resourceLink || ''
      ).trim();


    var assignedDate =
      normalizeDate(
        input.assignedDate
      );


    var dueDate =
      normalizeDate(
        input.dueDate
      );


    var maximumScore =
      parseInt(
        input.maximumScore,
        10
      );


    var mode =
      String(
        input.mode || 'draft'
      );


    if (!programSysId) {

      data.createSuccess = false;

      data.createMessage =
        'Training program is required.';

      return;

    }


    if (!name) {

      data.createSuccess = false;

      data.createMessage =
        'Assignment name is required.';

      return;

    }


    if (!assignedDate) {

      data.createSuccess = false;

      data.createMessage =
        'Assigned date is required.';

      return;

    }


    if (!dueDate) {

      data.createSuccess = false;

      data.createMessage =
        'Due date is required.';

      return;

    }


    if (
      dueDate < assignedDate
    ) {

      data.createSuccess = false;

      data.createMessage =
        'Due date cannot be before assigned date.';

      return;

    }


    if (
      isNaN(maximumScore) ||
      maximumScore <= 0
    ) {

      data.createSuccess = false;

      data.createMessage =
        'Maximum score must be greater than zero.';

      return;

    }


    /*
     * Verify trainer owns training.
     */

    var programGR =
      new GlideRecord(
        'x_snc_campus360_training_program'
      );


    programGR.addQuery(
      'sys_id',
      programSysId
    );


    programGR.addQuery(
      'trainer',
      trainerSysId
    );


    programGR.setLimit(1);
    programGR.query();


    if (!programGR.next()) {

      data.createSuccess = false;

      data.createMessage =
        'Training program does not belong to this trainer.';

      return;

    }


    var assignmentGR =
      new GlideRecord(
        'x_snc_campus360_assignment'
      );


    assignmentGR.initialize();


    if (
      assignmentGR.isValidField(
        'assignment_id'
      )
    ) {

      assignmentGR.setValue(
        'assignment_id',
        createAssignmentId()
      );

    }


    if (
      assignmentGR.isValidField(
        'assignment_name'
      )
    ) {

      assignmentGR.setValue(
        'assignment_name',
        name
      );

    }


    if (
      assignmentGR.isValidField(
        'batch'
      )
    ) {

      assignmentGR.setValue(
        'batch',
        programGR.getValue(
          'batch'
        ) || ''
      );

    }


    if (
      assignmentGR.isValidField(
        'description'
      )
    ) {

      assignmentGR.setValue(
        'description',
        description
      );

    }


    if (
      assignmentGR.isValidField(
        'assigned_date'
      )
    ) {

      assignmentGR.setValue(
        'assigned_date',
        assignedDate
      );

    }


    if (
      assignmentGR.isValidField(
        'due_date'
      )
    ) {

      assignmentGR.setValue(
        'due_date',
        dueDate
      );

    }


    if (
      assignmentGR.isValidField(
        'maximum_score'
      )
    ) {

      assignmentGR.setValue(
        'maximum_score',
        maximumScore
      );

    }


    if (
      assignmentGR.isValidField(
        'trainer'
      )
    ) {

      assignmentGR.setValue(
        'trainer',
        trainerSysId
      );

    }


    if (
      assignmentGR.isValidField(
        'training_program'
      )
    ) {

      assignmentGR.setValue(
        'training_program',
        programSysId
      );

    }


    if (
      assignmentGR.isValidField(
        'assignment_type'
      )
    ) {

      assignmentGR.setValue(
        'assignment_type',
        type
      );

    }


    if (
      assignmentGR.isValidField(
        'resource_link'
      )
    ) {

      assignmentGR.setValue(
        'resource_link',
        resourceLink
      );

    }


    if (
      assignmentGR.isValidField(
        'status'
      )
    ) {

      if (
        mode == 'publish'
      ) {

        assignmentGR.setValue(
          'status',
          getAssignmentPublishStatus()
        );

      } else {

        assignmentGR.setValue(
          'status',
          'Draft'
        );

      }

    }


    var newSysId =
      assignmentGR.insert();


    if (!newSysId) {

      data.createSuccess = false;

      data.createMessage =
        'Assignment could not be created.';

      return;

    }


    /*
     * Only published assignments
     * create submission records.
     */

    var createdSubmissionCount = 0;


    if (
      mode == 'publish'
    ) {

      createdSubmissionCount =
        createStudentSubmissionRecords(
          newSysId,
          programSysId
        );

    }


    data.createSuccess = true;


    if (
      mode == 'publish'
    ) {

      data.createMessage =
        'Assignment published successfully. ' +
        createdSubmissionCount +
        ' student submission record(s) created.';

    } else {

      data.createMessage =
        'Assignment saved as Draft.';

    }

  }


  /* =========================================================
     CREATE SUBMISSION RECORDS
     ========================================================= */

  function createStudentSubmissionRecords(
    assignmentSysId,
    programSysId
  ) {

    var count = 0;


    var enrollmentGR =
      new GlideRecord(
        'x_snc_campus360_training_enrollment'
      );


    enrollmentGR.addQuery(
      'training_program',
      programSysId
    );


    enrollmentGR.query();


    while (
      enrollmentGR.next()
    ) {

      var studentSysId =
        enrollmentGR.getValue(
          'student'
        );


      if (!studentSysId) {

        continue;

      }


      var submissionGR =
        new GlideRecord(
          'x_snc_campus360_assignment_submission'
        );


      if (
        !submissionGR.isValidField(
          'assignment'
        ) ||
        !submissionGR.isValidField(
          'student'
        )
      ) {

        continue;

      }


      submissionGR.addQuery(
        'assignment',
        assignmentSysId
      );


      submissionGR.addQuery(
        'student',
        studentSysId
      );


      submissionGR.setLimit(1);

      submissionGR.query();


      if (
        submissionGR.next()
      ) {

        continue;

      }


      submissionGR.initialize();


      submissionGR.setValue(
        'assignment',
        assignmentSysId
      );


      submissionGR.setValue(
        'student',
        studentSysId
      );


      if (
        submissionGR.isValidField(
          'submission_id'
        )
      ) {

        submissionGR.setValue(
          'submission_id',
          createSubmissionId()
        );

      }


      if (
        submissionGR.isValidField(
          'submission_status'
        )
      ) {

        submissionGR.setValue(
          'submission_status',
          'Not Submitted'
        );

      } else if (
        submissionGR.isValidField(
          'status'
        )
      ) {

        submissionGR.setValue(
          'status',
          'Not Submitted'
        );

      }


      var inserted =
        submissionGR.insert();


      if (inserted) {

        count++;

      }

    }


    return count;

  }


  /* =========================================================
     LOAD SUBMISSIONS
     ========================================================= */

  function loadSubmissions() {

    var assignmentSysId =
      String(
        input.assignment || ''
      ).trim();


    data.submissionData = {

      total: 0,

      submitted: 0,

      review: 0,

      evaluated: 0,

      rows: []

    };


    if (!assignmentSysId) {

      return;

    }


    var assignmentGR =
      new GlideRecord(
        'x_snc_campus360_assignment'
      );


    assignmentGR.addQuery(
      'sys_id',
      assignmentSysId
    );


    assignmentGR.addQuery(
      'trainer',
      trainerSysId
    );


    assignmentGR.setLimit(1);
    assignmentGR.query();


    if (!assignmentGR.next()) {

      return;

    }


    var submissionGR =
      new GlideRecord(
        'x_snc_campus360_assignment_submission'
      );


    if (
      !submissionGR.isValidField(
        'assignment'
      )
    ) {

      return;

    }


    submissionGR.addQuery(
      'assignment',
      assignmentSysId
    );


    submissionGR.orderBy(
      'student'
    );


    submissionGR.query();


    while (
      submissionGR.next()
    ) {

      var studentSysId =
        submissionGR.getValue(
          'student'
        ) || '';


      var student =
        getStudent(
          studentSysId
        );


      var status = 'Not Submitted';


      if (
        submissionGR.isValidField(
          'submission_status'
        )
      ) {

        status =
          submissionGR.getValue(
            'submission_status'
          ) || 'Not Submitted';

      } else if (
        submissionGR.isValidField(
          'status'
        )
      ) {

        status =
          submissionGR.getValue(
            'status'
          ) || 'Not Submitted';

      }


      var score = null;


      if (
        submissionGR.isValidField(
          'score'
        )
      ) {

        var rawScore =
          submissionGR.getValue(
            'score'
          );


        if (
          rawScore !== ''
        ) {

          score =
            parseInt(
              rawScore,
              10
            );


          if (
            isNaN(score)
          ) {

            score = null;

          }

        }

      }


      var submittedDate = '';


      if (
        submissionGR.isValidField(
          'submitted_date'
        )
      ) {

        submittedDate =
          submissionGR.getDisplayValue(
            'submitted_date'
          ) || '';

      }


      var feedback = '';


      if (
        submissionGR.isValidField(
          'trainer_feedback'
        )
      ) {

        feedback =
          submissionGR.getValue(
            'trainer_feedback'
          ) || '';

      }


      var submissionLink = '';


      if (
        submissionGR.isValidField(
          'submission_link'
        )
      ) {

        submissionLink =
          submissionGR.getValue(
            'submission_link'
          ) || '';

      }


      data.submissionData.total++;


      if (
        status == 'Submitted'
      ) {

        data.submissionData.submitted++;

      }


      if (
        status == 'Under Review'
      ) {

        data.submissionData.review++;

      }


      if (
        status == 'Evaluated'
      ) {

        data.submissionData.evaluated++;

      }


      data.submissionData.rows.push({

        sys_id:
          submissionGR.getUniqueValue(),

        studentSysId:
          studentSysId,

        studentName:
          student.name,

        studentId:
          student.id,

        initials:
          getInitials(
            student.name
          ),

        status:
          status,

        submittedDate:
          submittedDate,

        score:
          score,

        feedback:
          feedback,

        submissionLink:
          submissionLink

      });

    }

  }


  /* =========================================================
     SAVE EVALUATION
     ========================================================= */

  function saveEvaluation() {

    var submissionSysId =
      String(
        input.submission || ''
      ).trim();


    var status =
      String(
        input.status || ''
      ).trim();


    var feedback =
      String(
        input.feedback || ''
      ).trim();


    var scoreText =
      input.score === undefined ||
      input.score === null
        ? ''
        : String(
            input.score
          );


    if (!submissionSysId) {

      data.evaluationSuccess = false;

      data.evaluationMessage =
        'Submission record is missing.';

      return;

    }


    var submissionGR =
      new GlideRecord(
        'x_snc_campus360_assignment_submission'
      );


    if (
      !submissionGR.get(
        submissionSysId
      )
    ) {

      data.evaluationSuccess = false;

      data.evaluationMessage =
        'Submission record not found.';

      return;

    }


    if (
      !submissionGR.isValidField(
        'assignment'
      )
    ) {

      data.evaluationSuccess = false;

      data.evaluationMessage =
        'Assignment reference is missing.';

      return;

    }


    var assignmentSysId =
      submissionGR.getValue(
        'assignment'
      );


    var assignmentGR =
      new GlideRecord(
        'x_snc_campus360_assignment'
      );


    if (
      !assignmentGR.get(
        assignmentSysId
      )
    ) {

      data.evaluationSuccess = false;

      data.evaluationMessage =
        'Assignment not found.';

      return;

    }


    if (
      assignmentGR.getValue(
        'trainer'
      ) != trainerSysId
    ) {

      data.evaluationSuccess = false;

      data.evaluationMessage =
        'You cannot evaluate this submission.';

      return;

    }


    var maximumScore =
      parseInt(
        assignmentGR.getValue(
          'maximum_score'
        ),
        10
      ) || 0;


    var score = null;


    if (
      scoreText !== ''
    ) {

      score =
        parseInt(
          scoreText,
          10
        );


      if (
        isNaN(score)
      ) {

        data.evaluationSuccess = false;

        data.evaluationMessage =
          'Score must be a number.';

        return;

      }


      if (
        score < 0
      ) {

        data.evaluationSuccess = false;

        data.evaluationMessage =
          'Score cannot be negative.';

        return;

      }


      if (
        maximumScore > 0 &&
        score > maximumScore
      ) {

        data.evaluationSuccess = false;

        data.evaluationMessage =
          'Score cannot exceed maximum score of ' +
          maximumScore +
          '.';

        return;

      }

    }


    if (
      submissionGR.isValidField(
        'submission_status'
      )
    ) {

      if (status) {

        submissionGR.setValue(
          'submission_status',
          status
        );

      }

    } else if (
      submissionGR.isValidField(
        'status'
      )
    ) {

      if (status) {

        submissionGR.setValue(
          'status',
          status
        );

      }

    }


    if (
      submissionGR.isValidField(
        'score'
      )
    ) {

      if (score === null) {

        submissionGR.setValue(
          'score',
          ''
        );

      } else {

        submissionGR.setValue(
          'score',
          score
        );

      }

    }


    if (
      submissionGR.isValidField(
        'trainer_feedback'
      )
    ) {

      submissionGR.setValue(
        'trainer_feedback',
        feedback
      );

    }


    if (
      submissionGR.isValidField(
        'evaluated_by'
      )
    ) {

      /*
       * Your screenshot shows Evaluated By = TR001.
       * Since the field is reference-based,
       * store the trainer sys_id.
       */

      submissionGR.setValue(
        'evaluated_by',
        trainerSysId
      );

    }


    if (
      status == 'Evaluated' &&
      submissionGR.isValidField(
        'evaluated_date'
      )
    ) {

      submissionGR.setValue(
        'evaluated_date',
        new GlideDateTime()
      );

    }


    var result =
      submissionGR.update();


    data.evaluationSuccess =
      !!result;


    data.evaluationMessage =
      result
        ? 'Evaluation saved successfully.'
        : 'Unable to save evaluation.';

  }


  /* =========================================================
     ENROLLMENT
     ========================================================= */

  function getEnrollmentData(
    programSysId
  ) {

    var result = {

      studentCount: 0,

      totalProgress: 0,

      progressCount: 0,

      students: []

    };


    var enrollmentGR =
      new GlideRecord(
        'x_snc_campus360_training_enrollment'
      );


    enrollmentGR.addQuery(
      'training_program',
      programSysId
    );


    enrollmentGR.query();


    while (
      enrollmentGR.next()
    ) {

      var studentSysId =
        enrollmentGR.getValue(
          'student'
        );


      if (!studentSysId) {

        continue;

      }


      var student =
        getStudent(
          studentSysId
        );


      var progress = 0;


      if (
        enrollmentGR.isValidField(
          'progress_percentage'
        )
      ) {

        progress =
          parseFloat(
            enrollmentGR.getValue(
              'progress_percentage'
            )
          );


        if (
          isNaN(progress)
        ) {

          progress = 0;

        }

      }


      var attendance = null;


      if (
        enrollmentGR.isValidField(
          'attendance'
        )
      ) {

        attendance =
          parseFloat(
            enrollmentGR.getValue(
              'attendance'
            )
          );


        if (
          isNaN(attendance)
        ) {

          attendance = null;

        }

      }


      var assessment = null;


      if (
        enrollmentGR.isValidField(
          'assessment_score'
        )
      ) {

        assessment =
          parseFloat(
            enrollmentGR.getValue(
              'assessment_score'
            )
          );


        if (
          isNaN(assessment)
        ) {

          assessment = null;

        }

      }


      result.studentCount++;

      result.totalProgress +=
        progress;

      result.progressCount++;


      result.students.push({

        sys_id:
          studentSysId,

        name:
          student.name,

        id:
          student.id,

        initials:
          getInitials(
            student.name
          ),

        attendance:
          attendance === null
            ? '—'
            : Math.round(
                attendance
              ),

        progress:
          Math.round(
            progress
          ),

        assessment:
          assessment === null
            ? '—'
            : Math.round(
                assessment
              ),

        status:
          enrollmentGR.isValidField(
            'completion_status'
          )
            ? enrollmentGR.getValue(
                'completion_status'
              )
            : ''

      });

    }


    return result;

  }


  /* =========================================================
     STUDENT
     ========================================================= */

  function getStudent(
    studentSysId
  ) {

    var result = {

      id: '',

      name: 'Student'

    };


    if (!studentSysId) {

      return result;

    }


    var gr =
      new GlideRecord(
        'x_snc_campus360_student_master'
      );


    if (
      !gr.get(
        studentSysId
      )
    ) {

      return result;

    }


    result.id =
      gr.getValue(
        'student_id'
      ) || '';


    result.name =
      gr.getValue(
        'student_name'
      ) || 'Student';


    return result;

  }


  /* =========================================================
     ASSIGNMENTS
     ========================================================= */

  function getAssignments(
    programSysId
  ) {

    var list = [];


    var gr =
      new GlideRecord(
        'x_snc_campus360_assignment'
      );


    gr.addQuery(
      'training_program',
      programSysId
    );


    gr.addQuery(
      'trainer',
      trainerSysId
    );


    gr.orderByDesc(
      'sys_created_on'
    );


    gr.query();


    while (
      gr.next()
    ) {

      var assignmentSysId =
        gr.getUniqueValue();


      list.push({

        sys_id:
          assignmentSysId,

        id:
          gr.getValue(
            'assignment_id'
          ) || '',

        name:
          gr.getValue(
            'assignment_name'
          ) || '',

        type:
          gr.isValidField(
            'assignment_type'
          )
            ? gr.getValue(
                'assignment_type'
              ) || ''
            : '',

        description:
          gr.getValue(
            'description'
          ) || '',

        assignedDate:
          formatDate(
            gr.getValue(
              'assigned_date'
            )
          ),

        dueDate:
          formatDate(
            gr.getValue(
              'due_date'
            )
          ),

        maximumScore:
          parseInt(
            gr.getValue(
              'maximum_score'
            ),
            10
          ) || 0,

        status:
          gr.getValue(
            'status'
          ) || 'Draft',

        resourceLink:
          gr.isValidField(
            'resource_link'
          )
            ? gr.getValue(
                'resource_link'
              ) || ''
            : '',

        submissionCount:
          getSubmissionCount(
            assignmentSysId
          )

      });

    }


    return list;

  }


  function getSubmissionCount(
    assignmentSysId
  ) {

    var gr =
      new GlideRecord(
        'x_snc_campus360_assignment_submission'
      );


    if (
      !gr.isValidField(
        'assignment'
      )
    ) {

      return 0;

    }


    gr.addQuery(
      'assignment',
      assignmentSysId
    );


    gr.query();


    var count = 0;


    while (
      gr.next()
    ) {

      count++;

    }


    return count;

  }


  /* =========================================================
     ATTENDANCE
     ========================================================= */

  function loadAttendance() {

    var programSysId =
      String(
        input.training || ''
      ).trim();


    var date =
      normalizeDate(
        input.date
      );


    if (
      !programSysId ||
      !date
    ) {

      data.attendanceRows = [];

      data.attendanceDateError =
        'Training and date are required.';

      return;

    }


    var programGR =
      new GlideRecord(
        'x_snc_campus360_training_program'
      );


    programGR.addQuery(
      'sys_id',
      programSysId
    );


    programGR.addQuery(
      'trainer',
      trainerSysId
    );


    programGR.setLimit(1);
    programGR.query();


    if (!programGR.next()) {

      data.attendanceRows = [];

      data.attendanceDateError =
        'Training program not found.';

      return;

    }


    var startDate =
      formatDate(
        programGR.getValue(
          'start_date'
        )
      );


    var endDate =
      formatDate(
        programGR.getValue(
          'end_date'
        )
      );


    if (
      !isDateInsideRange(
        date,
        startDate,
        endDate
      )
    ) {

      data.attendanceRows = [];

      data.attendanceDateError =
        'Please select a date inside the training period.';

      return;

    }


    var enrollment =
      getEnrollmentData(
        programSysId
      );


    data.attendanceRows =
      buildAttendanceRows(
        programSysId,
        date,
        enrollment.students
      );


    data.attendanceDate =
      date;

  }


  function buildAttendanceRows(
    programSysId,
    attendanceDate,
    students
  ) {

    var rows = [];

    var existing = {};


    var gr =
      new GlideRecord(
        'x_snc_campus360_training_attendance'
      );


    gr.addQuery(
      'training_program',
      programSysId
    );


    gr.addQuery(
      'attendance_date',
      attendanceDate
    );


    gr.query();


    while (
      gr.next()
    ) {

      var studentSysId =
        gr.getValue(
          'student'
        );


      existing[
        studentSysId
      ] = {

        status:
          gr.getValue(
            'status'
          ) || '',

        remarks:
          gr.getValue(
            'remarks'
          ) || ''

      };

    }


    for (
      var i = 0;
      i < students.length;
      i++
    ) {

      var student =
        students[i];


      var saved =
        existing[
          student.sys_id
        ];


      rows.push({

        studentSysId:
          student.sys_id,

        name:
          student.name,

        id:
          student.id,

        initials:
          student.initials,

        status:
          saved
            ? saved.status
            : '',

        remarks:
          saved
            ? saved.remarks
            : ''

      });

    }


    return rows;

  }


  function saveAttendance() {

    var programSysId =
      String(
        input.training || ''
      ).trim();


    var date =
      normalizeDate(
        input.date
      );


    var records =
      input.records || [];


    if (
      !programSysId ||
      !date
    ) {

      data.saveSuccess = false;

      data.saveMessage =
        'Training program and date are required.';

      return;

    }


    var programGR =
      new GlideRecord(
        'x_snc_campus360_training_program'
      );


    programGR.addQuery(
      'sys_id',
      programSysId
    );


    programGR.addQuery(
      'trainer',
      trainerSysId
    );


    programGR.setLimit(1);

    programGR.query();


    if (!programGR.next()) {

      data.saveSuccess = false;

      data.saveMessage =
        'Training program not found.';

      return;

    }


    var startDate =
      formatDate(
        programGR.getValue(
          'start_date'
        )
      );


    var endDate =
      formatDate(
        programGR.getValue(
          'end_date'
        )
      );


    if (
      !isDateInsideRange(
        date,
        startDate,
        endDate
      )
    ) {

      data.saveSuccess = false;

      data.saveMessage =
        'Attendance must be inside the training period.';

      return;

    }


    var saved = 0;


    for (
      var i = 0;
      i < records.length;
      i++
    ) {

      var row =
        records[i];


      if (
        !row ||
        !row.studentSysId ||
        !row.status
      ) {

        continue;

      }


      if (
        !isValidAttendanceStatus(
          row.status
        )
      ) {

        continue;

      }


      if (
        !isStudentEnrolled(
          row.studentSysId,
          programSysId
        )
      ) {

        continue;

      }


      var attendanceGR =
        new GlideRecord(
          'x_snc_campus360_training_attendance'
        );


      attendanceGR.addQuery(
        'student',
        row.studentSysId
      );


      attendanceGR.addQuery(
        'training_program',
        programSysId
      );


      attendanceGR.addQuery(
        'attendance_date',
        date
      );


      attendanceGR.setLimit(1);

      attendanceGR.query();


      var isNew =
        !attendanceGR.next();


      if (isNew) {

        attendanceGR.initialize();


        if (
          attendanceGR.isValidField(
            'attendance_id'
          )
        ) {

          attendanceGR.setValue(
            'attendance_id',
            createAttendanceId()
          );

        }

      }


      attendanceGR.setValue(
        'trainer',
        trainerSysId
      );


      attendanceGR.setValue(
        'student',
        row.studentSysId
      );


      attendanceGR.setValue(
        'training_program',
        programSysId
      );


      attendanceGR.setValue(
        'attendance_date',
        date
      );


      attendanceGR.setValue(
        'status',
        row.status
      );


      attendanceGR.setValue(
        'remarks',
        String(
          row.remarks || ''
        ).substring(
          0,
          40
        )
      );


      var result;


      if (isNew) {

        result =
          attendanceGR.insert();

      } else {

        result =
          attendanceGR.update();

      }


      if (result) {

        saved++;

      }

    }


    data.saveSuccess =
      saved > 0;


    data.saveMessage =
      saved > 0
        ? saved +
          ' attendance record(s) saved successfully.'
        : 'No attendance records were saved.';

  }


  function isStudentEnrolled(
    studentSysId,
    programSysId
  ) {

    var gr =
      new GlideRecord(
        'x_snc_campus360_training_enrollment'
      );


    gr.addQuery(
      'student',
      studentSysId
    );


    gr.addQuery(
      'training_program',
      programSysId
    );


    gr.setLimit(1);

    gr.query();


    return gr.hasNext();

  }


  function isValidAttendanceStatus(
    status
  ) {

    return (
      status == 'Present' ||
      status == 'Absent' ||
      status == 'Late'
    );

  }


  /* =========================================================
     ASSIGNMENT PUBLISH STATUS
     ========================================================= */

  function getAssignmentPublishStatus() {

    var statuses = [
      'Open',
      'Published',
      'Active'
    ];


    for (
      var i = 0;
      i < statuses.length;
      i++
    ) {

      var choiceGR =
        new GlideRecord(
          'sys_choice'
        );


      choiceGR.addQuery(
        'name',
        'x_snc_campus360_assignment'
      );


      choiceGR.addQuery(
        'element',
        'status'
      );


      choiceGR.addQuery(
        'value',
        statuses[i]
      );


      choiceGR.addQuery(
        'inactive',
        false
      );


      choiceGR.setLimit(1);

      choiceGR.query();


      if (
        choiceGR.next()
      ) {

        return statuses[i];

      }

    }


    return 'Draft';

  }


  /* =========================================================
     ID HELPERS
     ========================================================= */

  function createAssignmentId() {

    var time =
      String(
        new GlideDateTime()
          .getNumericValue()
      );


    return (
      'ASN' +
      time.substring(
        time.length - 8
      )
    );

  }


  function createSubmissionId() {

    return (
      'SUB_' +
      String(
        new GlideDateTime()
          .getNumericValue()
      )
    );

  }


  function createAttendanceId() {

    return (
      'ATT_' +
      String(
        new GlideDateTime()
          .getNumericValue()
      )
    );

  }


  /* =========================================================
     DATE HELPERS
     ========================================================= */

  function formatDate(
    value
  ) {

    if (!value) {

      return '';

    }


    return String(value)
      .substring(
        0,
        10
      );

  }


  function normalizeDate(
    value
  ) {

    if (!value) {

      return '';

    }


    return String(value)
      .substring(
        0,
        10
      );

  }


  function isDateInsideRange(
    date,
    startDate,
    endDate
  ) {

    if (!date) {

      return false;

    }


    if (
      startDate &&
      date < startDate
    ) {

      return false;

    }


    if (
      endDate &&
      date > endDate
    ) {

      return false;

    }


    return true;

  }


  /* =========================================================
     INITIALS
     ========================================================= */

  function getInitials(
    name
  ) {

    if (!name) {

      return 'TR';

    }


    var parts =
      String(name)
        .trim()
        .split(/\s+/);


    if (
      parts.length == 1
    ) {

      return parts[0]
        .substring(
          0,
          2
        )
        .toUpperCase();

    }


    return (
      parts[0].charAt(0) +
      parts[
        parts.length - 1
      ].charAt(0)
    ).toUpperCase();

  }


})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
